@retail_bp.route('/suppliers/<string:sid>', methods=['PATCH'])
@mt_login_required
@mt_require_subsystem('retail')
@require_license_capability("retail.supplier.manage", restricted_mode_allowlist=RETAIL_RESTRICTED_ALLOWLIST)
@mt_require_capability(CAP_STOCK_ADJUST)
def update_supplier(sid):
    data = request.json or {}
    cid  = _cid()
    fields = {k: v for k, v in data.items() if k in ['name','phone','email','address','status','payment_terms']}
    if not fields:
        return jsonify({'status': 'error', 'message': 'No valid fields'}), 400
    conn = get_retail_conn()
    cur = conn.cursor()
    sets = ', '.join(f'{k}=?' for k in fields)
    params = list(fields.values())
    # launch-readiness Phase 6 stage 6a-i: same "bump only when a SYNCED
    # field actually changes" gate as update_customer above -- `fields` here
    # can be entirely `payment_terms`, which is not yet a first-class synced
    # column (SYNCED_SUPPLIER_FIELDS above / the comment on this route's own
    # SELECT below), so a payment_terms-only PATCH must bump nothing and
    # emit nothing, for the identical reason a credit-only customer PATCH
    # must not.
    touches_synced = bool(SYNCED_SUPPLIER_FIELDS & fields.keys())
    # launch-readiness Phase 6 stage 6b-iii-a (Step 3, restore paths must
    # clear the tombstone): same rule as update_product's identical comment
    # above -- `status` no longer marks deletion, so setting it to 'active'
    # must ALSO clear `deleted_at_utc`, in the SAME UPDATE. `restoring`
    # implies `touches_synced` (`status` is a member of
    # SYNCED_SUPPLIER_FIELDS, checked just above), so this can never fire on
    # a `payment_terms`-only PATCH that bumps nothing.
    restoring = fields.get('status') == 'active'
    if restoring:
        sets += ', deleted_at_utc=NULL'
    now = None
    if touches_synced:
        now = now_utc_iso()
        sets += ', row_version=row_version+1, updated_at_utc=?'
        params.append(now)
    cur.execute(f'UPDATE suppliers SET {sets} WHERE id=? AND company_id=?',
                params + [sid, cid])
    if cur.rowcount == 0:
        conn.close()
        return jsonify({'status': 'error', 'message': 'Supplier not found'}), 404
    _audit(conn, 'SUPPLIER_UPDATED', 'supplier', sid)
    # `status` and `payment_terms` included here (AUDIT-follow-up, 2026-08-10):
    # both are in this route's own `allowed` fields list above (payment_terms
    # can be PATCHed even though it's never set at creation -- create_supplier
    # doesn't accept it at all), so both were silently patchable locally but
    # never carried in the outbox payload. `status` completes the same
    # soft-delete/restore round-trip fix as update_product's SELECT above --
    # see sync_service.py's supplier upsert. `payment_terms` is included here
    # for forward-compatible payload completeness, matching this codebase's
    # existing "unknown field/entity type is silently ignored, not an error"
    # pattern (see sync_service.py's module docstring) -- sync_service.py's
    # supplier upsert does not yet apply it (payment_terms/credit_balance are
    # not first-class synced columns in this phase; see
    # docs/superpowers/specs/2026-08-07-retail-catalog-party-sync-expansion-design.md),
    # so it does not cross-device propagate yet even after this change.
    if touches_synced:
        # `deleted_at_utc` added to this SELECT (stage 6b-iii-a): the payload
        # must carry the CURRENT value -- NULL when `restoring` just cleared
        # it in the same UPDATE above, unchanged otherwise.
        row = conn.execute(
            "SELECT name,phone,email,address,status,payment_terms,deleted_at_utc,row_version,updated_at_utc "
            "FROM suppliers WHERE id=?", (sid,)).fetchone()
        # launch-readiness Phase 6 stage 6b-i (changed-field deltas):
        # `_changed_fields` is `SYNCED_SUPPLIER_FIELDS & fields.keys()`, NOT
        # `sorted(fields)` -- `fields` can also carry `payment_terms`, which
        # is in this route's `allowed` list but is not a first-class synced
        # column (see `touches_synced`'s own comment above). Same reasoning
        # as update_customer's identical guard.
        #
        # stage 6b-iii-a: `deleted_at_utc` added to the changed set ONLY when
        # `restoring` -- an ordinary status-untouched PATCH must not claim
        # `deleted_at_utc` changed, or the apply side's delta gate on that
        # column (sync_service.py's supplier branch) would clear a tombstone
        # this PATCH never touched.
        changed = (SYNCED_SUPPLIER_FIELDS & fields.keys()) | ({'deleted_at_utc'} if restoring else set())
        _queue_sync_event(cur, 'supplier', sid, 'update',
                           dict(row) | {'id': sid, '_changed_fields': sorted(changed)})
    conn.commit(); conn.close()
    _sync_nudge()
    return jsonify({'status': 'success'})

@retail_bp.route('/suppliers/<string:sid>', methods=['DELETE'])
@mt_login_required
@mt_require_subsystem('retail')
@require_license_capability("retail.supplier.manage", restricted_mode_allowlist=RETAIL_RESTRICTED_ALLOWLIST)
@mt_require_capability(CAP_STOCK_ADJUST)
def delete_supplier(sid):
    cid = _cid()
    conn = get_retail_conn()
    try:
        cur = conn.cursor()
        # launch-readiness Phase 6 stage 6a-i: row_version bumps in the SAME
        # UPDATE.
        #
        # launch-readiness Phase 6 stage 6b-iii-a (deletion stops overloading
        # `status`): `status='inactive'` is REMOVED -- see delete_product's
        # identical comment above for the full reasoning. `AND deleted_at_utc
        # IS NULL` makes a repeat delete of an already-tombstoned row a no-op
        # 404, not a re-stamp.
        now = now_utc_iso()
        cur.execute(
            "UPDATE suppliers SET deleted_at_utc=?, "
            "row_version=row_version+1, updated_at_utc=? "
            "WHERE id=? AND company_id=? AND deleted_at_utc IS NULL",
            (now, now, sid, cid))
        if cur.rowcount == 0:
            return jsonify({'status': 'error', 'message': 'Supplier not found'}), 404
        _audit(conn, 'SUPPLIER_DELETED', 'supplier', sid, 'Supplier deactivated')
        row = conn.execute("SELECT row_version FROM suppliers WHERE id=?", (sid,)).fetchone()
        # `_changed_fields` names only `deleted_at_utc` -- see delete_product's
        # identical comment above.
        _queue_sync_event(cur, 'supplier', sid, 'delete', {
            'id': sid, 'row_version': row['row_version'], 'updated_at_utc': now,
            'deleted_at_utc': now, '_changed_fields': ['deleted_at_utc'],
        })
        conn.commit()
    except sqlite3.IntegrityError as exc:
        conn.rollback()
        current_app.logger.warning("delete_supplier(%s) failed on a database constraint: %s", sid, exc)
        return jsonify({'status': 'error', 'message': 'This supplier could not be deleted.'}), 409
    except sqlite3.DatabaseError as exc:
        conn.rollback()
        current_app.logger.exception("delete_supplier(%s) failed: %s", sid, exc)
        return jsonify({'status': 'error', 'message': 'Could not delete this supplier.'}), 400
    finally:
        conn.close()
    _sync_nudge()
    return jsonify({'status': 'success', 'message': 'Supplier deactivated'})

# ── Supplier Contacts (PO-preview-by-supplier foundation, schema v6) ───────────
# A supplier can have several named contacts (orders/accounts/general), each
# with its own preferred channel -- core/retail/po_split.py's contact
# resolution ladder (resolve_contact) reads these to decide who a split
# group's slice would be routed to. CRUD only here: nothing dispatches
# anything yet (that lands with the routing routes later this week).

@retail_bp.route('/suppliers/<string:sid>/contacts', methods=['GET'])
@mt_login_required
@mt_require_subsystem('retail')
def list_supplier_contacts(sid):
    cid = _cid()
    conn = get_retail_conn()
    sup = conn.execute("SELECT id FROM suppliers WHERE id=? AND company_id=?", (sid, cid)).fetchone()
    if not sup:
        conn.close()
        return jsonify({'status': 'error', 'message': 'Supplier not found'}), 404
    rows = conn.execute(
        "SELECT * FROM supplier_contacts WHERE company_id=? AND supplier_id=? ORDER BY is_primary DESC, name",
        (cid, sid)
    ).fetchall()
    conn.close()
    return jsonify({'status': 'success', 'data': [dict(r) for r in rows]})

@retail_bp.route('/suppliers/<string:sid>/contacts', methods=['POST'])
@mt_login_required
@mt_require_subsystem('retail')
@require_license_capability("retail.supplier.manage", restricted_mode_allowlist=RETAIL_RESTRICTED_ALLOWLIST)
@mt_require_capability(CAP_STOCK_ADJUST)
def create_supplier_contact(sid):
    data = request.json or {}
    if not data.get('name'):
        return jsonify({'status': 'error', 'message': 'Contact name required'}), 400
    cid = _cid()
    conn = get_retail_conn()
    try:
        # launch-readiness Phase 6 stage 6b-iii-b: `AND deleted_at_utc IS
        # NULL` added -- no NEW contact may be attached to a deleted
        # supplier. `list_supplier_contacts` just above deliberately does
        # NOT gain this filter (reading EXISTING contacts of a since-deleted
        # supplier must not break), the same "write gates refuse a
        # tombstoned row, reads of historical/in-flight records do not
        # filter" rule this stage applies everywhere else.
        #
        # `AND status='active'` added alongside it (ROADMAP.md's "2026-08-28
        # -- Gaps surfaced by Phase 6b" entry): two deleted populations exist
        # here. A row deleted BEFORE tombstones existed carries
        # `status='inactive'` with `deleted_at_utc` still NULL -- the
        # deliberate no-backfill posture pinned by
        # `test_a_legacy_row_deleted_before_tombstones_is_still_hidden` --
        # while one deleted AFTER carries `status='active'` with the
        # tombstone set instead. Every catalogue READ already filters on
        # BOTH conditions for exactly this reason (drop either and the OTHER
        # population reappears); this WRITE gate now matches that rule
        # rather than catching only the newer half of it. Same pairing, same
        # reason, on `create_purchase_order`, `preview_po_split`,
        # `accept_reorder_request`, create_sale's credit-customer lookup,
        # and reorder_hook.py's product re-fetch -- not repeated in full at
        # each of those.
        sup = conn.execute(
            "SELECT id FROM suppliers WHERE id=? AND company_id=? AND status='active' AND deleted_at_utc IS NULL",
            (sid, cid)).fetchone()
        if not sup:
            return jsonify({'status': 'error', 'message': 'Supplier not found'}), 404
        role = data.get('role') or 'orders'
        is_primary = 1 if data.get('is_primary') else 0
        nid = str(_uuid.uuid4())
        # BEGIN IMMEDIATE: the primary-contact invariant below (clear, then
        # set) must not interleave with a concurrent request doing the same
        # thing for the same (supplier, role) -- same reasoning as
        # create_sale's stock-check BEGIN IMMEDIATE above.
        conn.execute("BEGIN IMMEDIATE")
        if is_primary:
            # Enforced invariant: at most one primary contact per (supplier, role).
            conn.execute(
                "UPDATE supplier_contacts SET is_primary=0 WHERE company_id=? AND supplier_id=? AND role=?",
                (cid, sid, role)
            )
        conn.execute("""
            INSERT INTO supplier_contacts (id,company_id,supplier_id,name,role,email,phone,whatsapp,channel_preference,is_primary,status)
            VALUES (?,?,?,?,?,?,?,?,?,?,'active')
        """, (nid, cid, sid, data['name'], role, data.get('email'), data.get('phone'), data.get('whatsapp'),
              data.get('channel_preference', 'whatsapp'), is_primary))
        _audit(conn, 'SUPPLIER_CONTACT_CREATED', 'supplier_contact', nid, data['name'])
        conn.commit()
        return jsonify({'status': 'success', 'data': {'id': nid}})
    except Exception as e:
        conn.rollback()
        return jsonify({'status': 'error', 'message': str(e)}), 500
    finally:
        conn.close()

@retail_bp.route('/suppliers/<string:sid>/contacts/<string:contact_id>', methods=['PATCH'])
@mt_login_required
@mt_require_subsystem('retail')
@require_license_capability("retail.supplier.manage", restricted_mode_allowlist=RETAIL_RESTRICTED_ALLOWLIST)
@mt_require_capability(CAP_STOCK_ADJUST)
def update_supplier_contact(sid, contact_id):
    data = request.json or {}
    cid = _cid()
    allowed = ['name', 'role', 'email', 'phone', 'whatsapp', 'channel_preference', 'is_primary', 'status']
    fields = {k: v for k, v in data.items() if k in allowed}
    if not fields:
        return jsonify({'status': 'error', 'message': 'No valid fields'}), 400
    conn = get_retail_conn()
    try:
        sup = conn.execute("SELECT id FROM suppliers WHERE id=? AND company_id=?", (sid, cid)).fetchone()
        if not sup:
            return jsonify({'status': 'error', 'message': 'Supplier not found'}), 404
        existing = conn.execute(
            "SELECT role FROM supplier_contacts WHERE id=? AND company_id=? AND supplier_id=?",
            (contact_id, cid, sid)
        ).fetchone()
        if not existing:
            return jsonify({'status': 'error', 'message': 'Contact not found'}), 404

        # Route to whichever role this contact will hold AFTER this PATCH
        # (its new role if role is being changed in the same request, else
        # its current one) -- the invariant is scoped per (supplier, role).
        role_for_invariant = fields.get('role', existing['role'])
        if 'is_primary' in fields:
            fields['is_primary'] = 1 if fields['is_primary'] else 0

        conn.execute("BEGIN IMMEDIATE")
        if fields.get('is_primary'):
            # Enforced invariant: at most one primary contact per (supplier, role).
            conn.execute(
                "UPDATE supplier_contacts SET is_primary=0 WHERE company_id=? AND supplier_id=? AND role=?",
                (cid, sid, role_for_invariant)
            )
        sets = ', '.join(f'{k}=?' for k in fields)
        conn.execute(f'UPDATE supplier_contacts SET {sets} WHERE id=? AND company_id=? AND supplier_id=?',
                     list(fields.values()) + [contact_id, cid, sid])
        _audit(conn, 'SUPPLIER_CONTACT_UPDATED', 'supplier_contact', contact_id)
        conn.commit()
        return jsonify({'status': 'success'})
    except Exception as e:
        conn.rollback()
        return jsonify({'status': 'error', 'message': str(e)}), 500
    finally:
        conn.close()

@retail_bp.route('/suppliers/<string:sid>/contacts/<string:contact_id>', methods=['DELETE'])
@mt_login_required
@mt_require_subsystem('retail')
@require_license_capability("retail.supplier.manage", restricted_mode_allowlist=RETAIL_RESTRICTED_ALLOWLIST)
@mt_require_capability(CAP_STOCK_ADJUST)
def delete_supplier_contact(sid, contact_id):
    """Soft-delete: sets status='inactive', never removes the row -- matches
    delete_supplier's own soft-delete convention just above, and keeps the
    contact's history (it may still be referenced by past split-preview
    audit trails once routing lands)."""
    cid = _cid()
    conn = get_retail_conn()
    sup = conn.execute("SELECT id FROM suppliers WHERE id=? AND company_id=?", (sid, cid)).fetchone()
    if not sup:
        conn.close()
        return jsonify({'status': 'error', 'message': 'Supplier not found'}), 404
    try:
        cur = conn.cursor()
        cur.execute(
            "UPDATE supplier_contacts SET status='inactive' WHERE id=? AND company_id=? AND supplier_id=?",
            (contact_id, cid, sid)
        )
        if cur.rowcount == 0:
            return jsonify({'status': 'error', 'message': 'Contact not found'}), 404
        _audit(conn, 'SUPPLIER_CONTACT_DELETED', 'supplier_contact', contact_id, 'Contact deactivated')
        conn.commit()
    except sqlite3.DatabaseError as exc:
        conn.rollback()
        current_app.logger.exception("delete_supplier_contact(%s,%s) failed: %s", sid, contact_id, exc)
        return jsonify({'status': 'error', 'message': 'Could not delete this contact.'}), 400
    finally:
        conn.close()
    return jsonify({'status': 'success', 'message': 'Contact deactivated'})

# ── Purchase Orders ───────────────────────────────────────────────────────────

@retail_bp.route('/purchase-orders', methods=['GET'])
@mt_login_required
@mt_require_subsystem('retail')
def list_purchase_orders():
    cid = _cid()
    conn = get_retail_conn()
    # Cross-tenant leak fix, 2026-08-29: `AND s.company_id=po.company_id`
    # added to the JOIN CONDITION, deliberately NOT to the WHERE clause --
    # same reasoning as list_products's categories-join comment (above,
    # this file). This is a LEFT JOIN and a PO with no supplier at all
    # (supplier_id IS NULL, a legitimate PO) must still be returned; a
    # condition in WHERE would silently drop every supplier-less PO from
    # this list instead of just blanking its supplier_name. Before this
    # fix, a purchase_orders row carrying another company's supplier_id
    # (create_purchase_order accepted one with no validation until this
    # same fix) joined straight across the tenant boundary and handed this
    # company that OTHER company's supplier NAME. Mirrors the existing
    # reverse-direction join in `list_suppliers` (above, this file):
    # `ON po.supplier_id=s.id AND po.company_id=s.company_id`.
    rows = conn.execute("""
        SELECT po.*, s.name as supplier_name
        FROM purchase_orders po LEFT JOIN suppliers s ON po.supplier_id=s.id AND s.company_id=po.company_id
        WHERE po.company_id=? ORDER BY po.created_at DESC LIMIT 100
    """, (cid,)).fetchall()
    conn.close()
    return jsonify({'status': 'success', 'data': [dict(r) for r in rows]})

def _po_stamp_and_queue_create(cur, po_id, order_journal_id):
    """W4a: finish a freshly-written purchase order for sync -- store the uid of
    the journal its order posted, then queue the order and every line.

    WHY THIS EXISTS. A PO lived only on the computer that typed it
    (`purchase_orders.id` is a per-computer integer and nothing was queued), so
    a sibling could not see, receive or cancel it, and an instalment typed there
    named the writer's integer and landed on an unrelated local PO. Both mint
    sites (create_purchase_order, accept_reorder_request) and the legacy boot
    backfill funnel through here so the wire shape cannot drift between them.

    `order_journal_id` is the id `gl.post_purchase_order` returned (None when
    it posted nothing, e.g. a zero-value order): the sibling needs the journal's
    UID, because the journal's own `source_id` is the writer's integer and
    means nothing there (the receipt and the cancel look the order journal up
    by this uid, see gl.po_order_journal).

    The payloads are LITERAL dicts at the call sites on purpose: the payload-
    coverage ratchet (retail_sync_payload_coverage_test.py) reads keys from
    literal dicts only (see 051bbfc4, where a tuple-stashed payload made it
    refuse to certify a whole table). `amount_paid` / `payment_status` are
    deliberately NOT on the wire: they are derived from the synced payments
    (po_core.recompute_po_paid) on every computer, so sending the writer's
    figure would only invite it to disagree with the rows that produce it.
    """
    # W4a verify F4: every read/write below is company-scoped (CLAUDE.md: any
    # query that skips company_id is a bug). The order's own company is the
    # scope: this helper is handed an id, not a company.
    po_cid = cur.execute("SELECT company_id FROM purchase_orders WHERE id=?", (po_id,)).fetchone()[0]
    if order_journal_id is not None:
        jrow = cur.execute("SELECT uid FROM gl_journals WHERE id=? AND company_id=?",
                           (order_journal_id, po_cid)).fetchone()
        if jrow and jrow['uid']:
            cur.execute("UPDATE purchase_orders SET order_journal_uid=? WHERE id=? AND company_id=?",
                        (jrow['uid'], po_id, po_cid))
    # W4a verify F1: stamp how many lines this order has. Every caller has
    # inserted ALL its lines before reaching here (create, reorder-accept) or
    # holds them all locally (the legacy backfill), so COUNT(*) is the full set.
    # The header and each line are SEPARATE sync events and a line can park on
    # a product that has not arrived; a sibling that received on the header
    # alone would move the books for the whole order and the stock for only the
    # lines present. receive_purchase_order refuses while it holds fewer lines
    # than this number. Company-scoped like every write here.
    cur.execute(
        "UPDATE purchase_orders SET item_count="
        "(SELECT COUNT(*) FROM purchase_order_items WHERE po_id=purchase_orders.id) "
        "WHERE id=? AND company_id=?", (po_id, po_cid))
    po = cur.execute("SELECT * FROM purchase_orders WHERE id=? AND company_id=?",
                     (po_id, po_cid)).fetchone()
    branch_uid = _branch_uid(cur.connection, po['branch_id']) if po['branch_id'] else None
    _queue_sync_event(cur, 'purchase_order', po['uid'], 'create', {
        'uid': po['uid'], 'po_number': po['po_number'], 'supplier_id': po['supplier_id'],
        'branch_uid': branch_uid, 'status': po['status'], 'subtotal': po['subtotal'],
        'tax_total': po['tax_total'], 'total': po['total'], 'notes': po['notes'],
        'ordered_at': po['ordered_at'], 'received_at': po['received_at'],
        'created_at': po['created_at'], 'due_date': po['due_date'],
        'order_journal_uid': po['order_journal_uid'],
        'split_group_id': po['split_group_id'], 'split_index': po['split_index'],
        'split_count': po['split_count'], 'routing_status': po['routing_status'],
        'routed_channel': po['routed_channel'], 'routed_at': po['routed_at'],
        'routed_to': po['routed_to'], 'idempotency_key': po['idempotency_key'],
        'item_count': po['item_count'],
        # W4a-2: which rule books this order's supplier debt ('receipt' = at
        # delivery, 'order' = at the order, the pre-v46 way). Sent so every
        # computer applies the SAME rule; a payload without it applies as
        # 'order' (a v45 writer). cancelled_at/closed_at ride along so an order
        # announced after it was cancelled/closed (the boot backfill) arrives in
        # that state without a separate header update.
        'ap_basis': po['ap_basis'], 'cancelled_at': po['cancelled_at'],
        'closed_at': po['closed_at'],
    })
    for it in cur.execute("SELECT * FROM purchase_order_items WHERE po_id=? ORDER BY id",
                          (po_id,)).fetchall():
        _queue_sync_event(cur, 'purchase_order_item', it['uid'], 'create', {
            'uid': it['uid'], 'po_uid': po['uid'], 'product_id': it['product_id'],
            'quantity': it['quantity'], 'unit_cost': it['unit_cost'], 'total': it['total'],
            'received_qty': it['received_qty'],
        })


def _classify_po_payments(cur, po, eps):
    """W4a verify F2: sort the payments naming legacy order `po` by WHO recorded
    them. Returns (local, sibling, unprovable) lists of payment rows.

    WHY THIS EXISTS. Before W4a a sibling's instalment was applied verbatim:
    `related_id` is the WRITER's purchase_orders.id, which here names THIS
    computer's unrelated order. Emitting a po_link for every same-supplier
    payment (the first cut) therefore tied a sibling's money to our order and
    the recompute counted it (measured: 101 'paid' on an order this computer
    paid 1 on).

    ORIGIN RULE -- the only signal that cannot be forged or shared:
    the computer that recorded a payment posted its GL journal LOCALLY, so
    that journal's `source_id` is a real integer; a journal that arrived by
    sync has `source_id` NULL (sync_service derives source_id only for sale
    and return journals). `payments.device` is client-supplied and
    `created_by` users sync to every computer, so neither can say.

      LOCAL      (a) a `po_payment` journal with source_id = this order and
                     source_uid = the payment's uid (an instalment), OR
                 (b) the order's own LOCAL order journal credits cash (1000)
                     by the payment's amount: the DOWN PAYMENT, which posts no
                     po_payment journal of its own. One cash line matches at
                     most ONE payment (lowest payments.id first), so a second
                     payment of the same amount is not mistaken for it.
      SIBLING    journals exist for the payment's uid and NONE is local.
      UNPROVABLE no journal either way (pre-v38 books, a supplier-less order).
                 Left exactly as it was and never announced: RESIDUAL -- such
                 a payment keeps counting toward this order and is not linked
                 on siblings, because guessing is how the bug above happened.
    """
    cid = po['company_id']
    pays = cur.execute(
        "SELECT id, uid, amount FROM payments WHERE company_id=? AND related_type='po' "
        "AND related_id=? ORDER BY id", (cid, po['id'])).fetchall()
    if not pays:
        return [], [], []
    try:
        cash_lines = [float(r[0]) for r in cur.execute(
            "SELECT l.credit FROM gl_journals j "
            "JOIN gl_journal_lines l ON l.journal_id = j.id "
            "JOIN gl_accounts a ON a.id = l.account_id AND a.company_id = j.company_id "
            "WHERE j.company_id=? AND j.source_type='purchase_order' AND j.source_id=? "
            "AND j.reversed_journal_id IS NULL AND a.code=? AND l.credit > 0 ORDER BY l.id",
            (cid, po['id'], gl.ACCOUNT_CASH)).fetchall()]
    except sqlite3.OperationalError:
        cash_lines = []            # no books tables yet: nothing is provable
    local, sibling, unprovable = [], [], []
    for pay in pays:
        if not pay['uid']:
            unprovable.append(pay)
            continue
        try:
            sources = [r[0] for r in cur.execute(
                "SELECT source_id FROM gl_journals WHERE company_id=? AND source_type='po_payment' "
                "AND source_uid=?", (cid, pay['uid'])).fetchall()]
        except sqlite3.OperationalError:
            sources = []
        if po['id'] in sources:                                   # (a)
            local.append(pay)
        elif sources and all(s is None for s in sources):         # synced in: a sibling's
            sibling.append(pay)
        else:
            hit = next((i for i, line in enumerate(cash_lines)
                        if abs(line - float(pay['amount'] or 0)) <= eps), None)
            if hit is not None:                                   # (b) the down payment
                cash_lines.pop(hit)
                local.append(pay)
            else:
                unprovable.append(pay)
    return local, sibling, unprovable


def backfill_legacy_purchase_orders(conn):
    """W4a boot step: announce every purchase order that existed BEFORE v45.

    Schema v45 stamps a uid on every legacy order and sets
    `sync_backfill_pending=1`; nothing was ever queued for them, so a second
    computer joining later would never learn them (and a payment event would
    name an order it has never seen). This queues, per pending order and in ONE
    transaction each: the order + its lines (`_po_stamp_and_queue_create`), a
    status `update` when the order is no longer pending, and a `po_link` for
    every payment that names it, then clears the flag. Running it again emits
    nothing -- the flag is the once-only latch -- and a failure on one order
    rolls back just that order, so the next boot retries it.

    The `po_link` is how a pre-v45 PAYMENT (its `create` event carried only the
    writer's integer `related_id`, never a uid) gets pinned to the right order on
    the receiver. `related_id` is a bare per-computer integer, so a payment that
    merely carries this order's integer may be a SIBLING's. W4a verify F2 decides
    by ORIGIN, not by supplier (see `_classify_po_payments`): only payments this
    computer provably recorded are linked; a sibling's is detached from the
    order and not counted; the rest are left alone and counted in one INFO line.
    RESIDUAL, recorded not fixed: (1) an unprovable payment (no journal either
    way) is neither linked nor detached; (2) only orders that existed at the
    upgrade are scanned, so a stale sibling row that happens to carry the
    integer of an order typed AFTER the upgrade is not found here.

    Emitted even on a single-computer shop (harmless; the outbox is how a later
    second computer learns the history) -- same stance as
    gl.backfill_legacy_journals. Returns the number of orders announced."""
    cols = {r[1] for r in conn.execute("PRAGMA table_info(purchase_orders)").fetchall()}
    if 'sync_backfill_pending' not in cols or 'uid' not in cols:
        return 0          # pre-v45 shape: nothing stamped yet, retry next boot
    done = 0
    unlinked = 0
    pending = [(r[0], r[1]) for r in conn.execute(
        "SELECT id, company_id FROM purchase_orders WHERE sync_backfill_pending=1 ORDER BY id").fetchall()]
    for po_id, po_company in pending:
        cur = conn.cursor()
        try:
            cur.execute("SAVEPOINT po_backfill")
            po = cur.execute("SELECT * FROM purchase_orders WHERE id=? AND company_id=?",
                             (po_id, po_company)).fetchone()
            _po_stamp_and_queue_create(cur, po_id, None)
            # W4a-2: the old `status` update that used to follow is gone. A
            # cancelled/closed order now announces that in its create payload
            # (cancelled_at/closed_at), and a received order's receipts are
            # facts every computer derives for itself (the v46 migration's
            # legacy receipt) -- they are NEVER queued from here.
            local, sibling, unprovable = _classify_po_payments(
                cur, po, _money_epsilon(_company_currency(conn, po['company_id'])))
            for pay in local:
                _queue_sync_event(cur, 'payment', pay['uid'], 'po_link',
                                  {'uid': pay['uid'], 'po_uid': po['uid']})
            for pay in sibling:
                # A sibling's payment that the old verbatim apply pinned to this
                # order by the WRITER's integer. Detach (money still counts for
                # the supplier: that balance is keyed on party_id); the sibling
                # re-announces it by po_uid, which resolves to the right order.
                cur.execute("UPDATE payments SET related_id=NULL WHERE id=? AND company_id=?",
                            (pay['id'], po['company_id']))
            if local or sibling:
                po_core.recompute_po_paid(conn, po['company_id'], po_id,
                                          _money_epsilon(_company_currency(conn, po['company_id'])))
            cur.execute("UPDATE purchase_orders SET sync_backfill_pending=0 WHERE id=? AND company_id=?",
                        (po_id, po_company))
            cur.execute("RELEASE SAVEPOINT po_backfill")
            done += 1
            unlinked += len(unprovable)
        except Exception:  # noqa: BLE001 -- one order must not stop the rest, nor the boot
            log.exception('purchase-order sync backfill failed for PO %s -- will retry next boot', po_id)
            try:
                cur.execute("ROLLBACK TO SAVEPOINT po_backfill")
                cur.execute("RELEASE SAVEPOINT po_backfill")
            except Exception:  # noqa: BLE001
                pass
    if unlinked:
        log.info('W4a backfill: %d PO payments left unlinked (origin unprovable)', unlinked)
    if done:
        conn.commit()
    return done


@retail_bp.route('/purchase-orders', methods=['POST'])
@mt_login_required
@mt_require_subsystem('retail')
@require_license_capability("retail.purchase.create", restricted_mode_allowlist=RETAIL_RESTRICTED_ALLOWLIST)
@mt_require_capability(CAP_STOCK_ADJUST)
def create_purchase_order():
    data = request.json or {}
    cid  = _cid()
    items = data.get('items', [])
    if not items:
        return jsonify({'status': 'error', 'message': 'At least one item required'}), 400

    # AUDIT: same asymmetry class as void_payment's B1 fix above -- ordering
    # a PO is retail.stock.adjust (a manager-level action, and this route's
    # own decorator floor stays exactly that), but this route's OWN
    # amount_paid field posts a real money-out payment to the supplier via
    # _record_payment below (~1310ish; the identical action supplier_payment
    # and pay_purchase_order both require CAP_EMPLOYEES for, with an
    # explicit comment on supplier_payment that receiving a delivery and
    # paying for it are different authorities). Without this check that
    # CAP_EMPLOYEES gate was decoration only: a manager correctly refused
    # by both dedicated payment routes could still pay a supplier by typing
    # a number into amount_paid on a brand-new PO instead.
    #
    # Refuses the WHOLE request rather than creating the PO and silently
    # dropping amount_paid, on purpose. This route has no partial-success
    # shape in its response (unlike execute_import's `warnings` list) to
    # hang a "payment not recorded" notice on, and silently dropping a
    # figure someone typed into a money field is how a shop ends up
    # believing a supplier was paid when they were not -- the PO would show
    # payment_status='unpaid' with no error, which reads as this route
    # working, not as it refusing part of the request. Refusing outright
    # gives the caller nothing rather than a wrong thing; they can retry
    # with amount_paid omitted and have an owner record the down-payment
    # through pay_purchase_order once CAP_EMPLOYEES is available.
    #
    # amount_paid is computed HERE, ONCE, via the same _money() coercion and
    # the same `> _money_epsilon(currency)` threshold the real payment write
    # uses further down (a 2dp-era hardcoded 0.005 until the epsilon sweep) --
    # that single local is reused rather than recomputed, so no numeric
    # spelling (absent, 0, negative, a numeric string, a float that rounds
    # up under ROUND_HALF_UP) can reach _record_payment without first
    # passing through this exact check. Negative values fall out of scope
    # for the same reason they already fell out of the pre-existing
    # `if amount_paid > _eps:` guard below: they were never going to post a
    # payment either way.
    #
    # Checked BEFORE _ensure_credit_schema()/_next_ref() -- this route holds
    # no explicit BEGIN IMMEDIATE, but _next_ref() is the first statement
    # that writes (it increments doc_sequences), so the refusal has to run
    # even earlier than that to have no side effect at all, same rule
    # void_payment's check documents relative to its own write.
    #
    # `conn` IS opened here, ahead of that refusal -- narrower than it looks.
    # get_retail_conn() is a bare sqlite3.connect(); _company_currency() is a
    # single read-only SELECT that never raises (see its own docstring). No
    # WRITE happens before the capability check below: _ensure_credit_schema
    # and _next_ref, the two statements the comment above is actually about,
    # both still run strictly after it, unchanged.
    conn = get_retail_conn()
    currency = _company_currency(conn, cid)
    # CLAMPED AT ZERO, and the clamp belongs HERE rather than at any of the
    # four places that read this local. The comment block above is right that
    # a negative amount_paid never reached _record_payment -- the `> _eps`
    # gate already excluded it -- but it stops one line short: the same
    # negative then flows into `balance = _money(total - amount_paid)` further
    # down, and `15 - (-50)` is `65`. A PO for 15 with `amount_paid: -50`
    # therefore pushed SIXTY-FIVE onto the supplier's AP through
    # _adjust_credit, silently, while paying nothing out. The shop's books
    # said it owed 50 more than it did, on a document the route returns 200
    # for and a test deliberately allows (retail_route_capability_matrix_
    # test.py's `negative -> allowed` case, which is correct about the
    # PAYMENT half and was never asserting anything about the AP half).
    #
    # Found by schema v38's general ledger, not by reading: posting this
    # same PO raised GeneralLedgerImbalanceError "debits=15.000
    # credits=65.000 diff=-50.000", because double-entry cannot express
    # "inventory worth 15 was financed by 65 of supplier credit" and the
    # single-sided subledger could. That is the whole argument for the GL
    # sitting inside the document's own transaction.
    #
    # Clamping the ONE local the route computes once fixes every consumer
    # together -- the capability gate (unchanged: a negative never passed
    # `> _eps` and 0.0 still does not), the stored `purchase_orders.
    # amount_paid` column, `payment_status` (still 'unpaid' either way),
    # the AP `_adjust_credit`, and the GL posting -- so they cannot drift
    # apart again the way they just did.
    amount_paid = max(0.0, _money(data.get('amount_paid', 0), currency))
    _eps = _money_epsilon(currency)
    if amount_paid > _eps:
        if not session_has_capability(CAP_EMPLOYEES):
            conn.close()
            return jsonify({'status': 'error', 'message': SUPPLIER_PAYMENT_DENIED_MESSAGE}), 403
        # I-10 (P0 item #2, reviewer finding): CAP_EMPLOYEES alone is not
        # enough once a down-payment is posted here -- it is the exact same
        # money-out action supplier_payment and pay_purchase_order's own
        # amount_paid branch both require the owner for (see
        # _require_company_admin's own docstring). Without this, the
        # branch-staff delegation toggle's CAP_EMPLOYEES grant (employees.js)
        # let a manager pay a supplier by typing a number into a brand-new
        # PO's amount_paid instead of being refused by the two dedicated
        # payment routes -- reopening exactly the "weaker second path" the
        # capability matrix's Fix 1 closed. amount_paid=0 (the far more
        # common case -- receiving/ordering stock) stays on CAP_EMPLOYEES
        # alone; only the money-out half needs the owner.
        admin_guard = _require_company_admin()
        if admin_guard is not None:
            conn.close()
            return admin_guard

    _ensure_credit_schema(conn)
    # 2026-08-28: defense-in-depth error containment, same shape and same
    # reasoning as delete_category's own Fix 4 comment (above, this file).
    # `purchase_orders.po_number` carries a bare (not per-company, not
    # per-device) UNIQUE constraint (database/schema.py), and before the
    # company+device fragments added to po_number below, two companies on
    # one install minting their FIRST purchase order both generated
    # "PO-000001" and collided on it. This route had NO try/except around
    # that INSERT at all: the resulting sqlite3.IntegrityError escaped
    # straight into Flask's default 500 handler, WITH the connection never
    # closed on that path -- leaked for the rest of the process, holding
    # the WAL write lock it took on its first write, so every OTHER write
    # anywhere in this database then failed with "database is locked". One
    # colliding PO took the whole install down, not just that request (see
    # ROADMAP.md's 2026-08-28 "po_number collides across companies" entry).
    #
    # The fragments below make that SPECIFIC collision unreachable in
    # practice, but the containment stays regardless and is not redundant
    # with it: this is what stops the NEXT constraint added anywhere near
    # this table from reintroducing the exact same install-wide outage,
    # exactly as delete_category's own comment already argues for that
    # route.
    try:
        cur = conn.cursor()
        # launch-readiness Phase 6 stage 6b-iii-b: this route had NO product
        # existence check at all before this stage -- `purchase_order_items` was
        # inserted straight from the request's `product_id`s with no read of
        # `products` in between. `preview_po_split` just below in this file
        # already gained a `company_id=? AND deleted_at_utc IS NULL` product read
        # at stage 6b-iii-a for the identical reason (it is a WRITE gate that
        # plans a PO a caller may go on to actually create, not a display list);
        # this is that same read, added here so a NEW PO cannot be raised for a
        # deleted product either. `list_purchase_orders`/`get_purchase_order`/
        # `receive_purchase_order` deliberately do NOT gain this filter -- a PO
        # already raised for a since-deleted product must stay receivable, or
        # stock already in transit becomes permanently unreceivable (same
        # "existing pending/in-flight documents do not filter" rule stage
        # 6b-iii-a established for a pending reorder request against a deleted
        # product; see reorder_hook.py's own comment for the write-side half of
        # that same rule).
        #
        # `status='active'` joins the tombstone check for the two-population
        # reason `create_supplier_contact`'s comment (above, this file) spells
        # out in full -- a product deleted before tombstones existed never got a
        # `deleted_at_utc` stamp, so the tombstone filter alone would miss it and
        # let it straight back onto a brand-new PO.
        po_product_ids = {item['product_id'] for item in items}
        if po_product_ids:
            placeholders = ','.join('?' * len(po_product_ids))
            valid_rows = conn.execute(
                f"SELECT id FROM products WHERE company_id=? AND status='active' AND deleted_at_utc IS NULL AND id IN ({placeholders})",
                [cid, *po_product_ids]
            ).fetchall()
            missing_ids = po_product_ids - {r['id'] for r in valid_rows}
            if missing_ids:
                return jsonify({'status': 'error',
                                 'message': f'Unknown product_id: {sorted(missing_ids)[0]}'}), 400

        # Cross-tenant leak fix, 2026-08-29 (ROADMAP.md's "create_purchase_
        # order still has no cross-tenant validation on supplier_id" entry):
        # `supplier_id` carried NO validation of any kind before this block
        # -- not existence, not company ownership, not tombstone. A caller
        # in company A could pass company B's supplier_id straight through;
        # the INSERT below has no FK enforcing a company_id match, so the
        # row landed cleanly, and `list_purchase_orders`/`get_purchase_order`
        # (below in this file) joined suppliers with no company condition on
        # the join either, so the very next read handed company A company
        # B's supplier NAME. This closes the WRITE half; the join fix on
        # those two read routes closes the READ half -- neither is
        # sufficient alone, since validation here does nothing for rows
        # already written, and the join fix alone would still let a bad row
        # be written (and would silently blank its supplier name on read
        # rather than refuse the write).
        #
        # `supplier_id` stays OPTIONAL: `if supplier_id:` guards this
        # exactly like every other `if supplier_id:` branch already in this
        # function (the AP-ledger credit adjustment below) -- a PO with no
        # supplier at all is legitimate and must not be refused. Same
        # shape, same error style, same status code as the product check
        # immediately above: 400, with the offending id named rather than a
        # generic "invalid" message. `status='active' AND deleted_at_utc IS
        # NULL` is the same tombstone/legacy-delete pairing
        # `create_supplier_contact`'s comment (above, this file) explains in
        # full.
        supplier_id = data.get('supplier_id')
        if supplier_id:
            valid_supplier = conn.execute(
                "SELECT id FROM suppliers WHERE id=? AND company_id=? AND status='active' AND deleted_at_utc IS NULL",
                (supplier_id, cid)
            ).fetchone()
            if not valid_supplier:
                return jsonify({'status': 'error',
                                 'message': f'Unknown supplier_id: {supplier_id}'}), 400
        # STOCK-BOOKS verify F3: an order with an UNPAID remainder must name the
        # supplier it is owed to. A supplier-less credit PO books Dr 1260 for
        # only the paid part (the unpaid part has no AP line -- the supplier
        # subledger cannot hold it), so the goods would arrive worth more than
        # the books ever recorded and the Inventory tie would read "differs".
        # A FULLY PAID supplier-less order stays allowed: nothing is owed.
        _po_total_check = _money(sum(float(i.get('unit_cost', 0)) * float(i.get('quantity', 0)) for i in items), currency)
        if not supplier_id and (_po_total_check - amount_paid) > _eps:
            return jsonify({'status': 'error', 'code': 'SUPPLIER_REQUIRED_FOR_CREDIT_PO',
                            'message': 'Choose the supplier you will owe, or pay the order in full.'}), 409

        # Launch-readiness chain wave C1 (ROADMAP.md's 2026-08-30 "the
        # multi-branch capture defect" entry): same cross-tenant leak shape
        # as supplier_id immediately above -- `data.get('branch_id')` was
        # never validated, so a caller in company A could silently address
        # company B's branch. Resolved through _resolve_working_branch (see
        # its own docstring for the explicit -> pinned -> self-heal order);
        # a NEW PO now takes this device's pinned branch, not just
        # create_sale, when the caller sends no branch_id at all.
        branch_id, branch_err = _resolve_working_branch(conn, cid, data.get('branch_id'))
        if branch_err:
            return branch_err
        # purchase_orders.po_number carries a bare (not company-scoped, not
        # device-scoped) UNIQUE constraint, but _next_ref()'s counter resets
        # per company AND is a per-DEVICE table (`doc_sequences` is never
        # synced -- see _device_doc_discriminator's docstring). Two
        # different companies' first PO would otherwise both generate
        # "PO-000001" and collide in this shared multi-tenant database
        # (fixed first, appending a company fragment); two DEVICES on the
        # SAME company would independently generate the identical
        # "PO-000001-<cid8>" and collide the moment sync relayed both to a
        # third device -- the same AUDIT-032B wedge-sync failure chain
        # create_sale's identical fix closes (see
        # _device_doc_discriminator's docstring). Appending both fragments
        # keeps the sequential part human-readable/searchable while
        # guaranteeing global uniqueness without altering the shared
        # _next_ref helper or its format for other doc types.
        #
        # Aseel-parity wave A-PAR (schema v34): if THIS terminal owns a
        # configured 'po' book, its clean series number is minted instead
        # -- `resolve_series` can only ever return a book this exact
        # terminal_uid claimed (see doc_series.py's own docstring), so an
        # install that never configures one takes the UNCHANGED legacy path
        # below, byte for byte, fragments included. Identical treatment at
        # accept_reorder_request's own second po_number mint site --
        # retail_po_number_uniqueness_test.py exists precisely because
        # fixing one PO mint site and not the other left a real bug fully
        # live, and the same rule applies to this feature.
        _po_series = _resolve_series_gated(conn, cid, 'po')
        if _po_series is not None:
            po_number = doc_series.allocate(conn, _po_series)
        else:
            po_number = _mint_legacy_doc_number(conn, cid, 'po')
        total = _money(sum(float(i.get('unit_cost', 0)) * float(i.get('quantity', 0)) for i in items), currency)
        # supplier_id was already resolved and validated above.
        # `_eps` is `_money_epsilon(currency)`, resolved once at the top of
        # this route from the SAME `currency` every figure here is quantized
        # at -- half a fil on JOD, half a cent on USD. It replaced a
        # hardcoded 0.005 which, on a 3-decimal currency, called a PO with
        # five fils still outstanding fully 'paid' and a five-fil
        # down-payment 'unpaid'. Both of this line's comparisons and the two
        # money writes below use the one local, so 'paid'/'partial'/'unpaid',
        # the payment row and the AP credit can never disagree about whether
        # a figure is zero.
        payment_status = 'paid' if amount_paid >= total - _eps else ('partial' if amount_paid > _eps else 'unpaid')
        # W4a: the order carries its own wire identity (`uid`) from birth, and
        # so does every line -- a sibling names them by uid, never by this
        # computer's integer id. `amount_paid`/`payment_status` are inserted at
        # 0/'unpaid' and DERIVED from the down-payment row below by
        # recompute_po_paid, the same function every other computer runs, so
        # the figure is never a stored increment that can drift.
        po_uid = _new_uid()
        cur.execute("""
            INSERT INTO purchase_orders (company_id,po_number,supplier_id,branch_id,status,subtotal,total,notes,ordered_at,
                                         amount_paid,payment_status,due_date,uid,ap_basis)
            VALUES (?,?,?,?,?,?,?,?,?,0,'unpaid',?,?,'receipt')
        """, (cid, po_number, supplier_id, branch_id,
              'pending', total, total, data.get('notes',''),
              datetime.now().strftime('%Y-%m-%d'), data.get('due_date'), po_uid))
        po_id = cur.lastrowid
        for item in items:
            line = float(item.get('unit_cost',0)) * float(item.get('quantity',0))
            cur.execute("""
                INSERT INTO purchase_order_items (po_id,product_id,quantity,unit_cost,total,uid)
                VALUES (?,?,?,?,?,?)
            """, (po_id, item['product_id'], item['quantity'], item.get('unit_cost',0), line, _new_uid()))
        # AP ledger: record any down-payment now; push the unpaid balance onto supplier AP.
        down_pay_uid = _new_uid()
        down_pay_ref = None
        if amount_paid > _eps:
            down_pay_ref = _record_payment(conn, cid, 'supplier', supplier_id, 'out', amount_paid,
                                           method=data.get('method', 'cash'), related_type='po', related_id=po_id,
                                           doc_type='supplier_payment', currency=currency, pay_uid=down_pay_uid)
        # Derived, not stored-by-hand (see the insert above). Equals the figure
        # computed from the request, by construction: the one payment row.
        _, payment_status = po_core.recompute_po_paid(conn, cid, po_id, _eps)
        balance = _money(total - amount_paid, currency)
        if supplier_id:
            # v44: the PO row and its down-payment are written above, so the
            # supplier's figure is re-derived from them (never moved by delta).
            _refresh_party_balance(conn, 'suppliers', supplier_id, cid, currency)
        # W4a-2: NO order journal. Supplier debt (and the stock it buys) is
        # booked when the goods ARRIVE, once per receipt (receive_purchase_order),
        # so a typed order that never comes leaves no debt and no stock in the
        # books -- it used to book Dr 1260 / Cr AP here and the supplier's
        # balance claimed money for goods that were never delivered. A down
        # payment is the one thing that IS money out today: it posts on its own
        # (Dr AP, or Dr 1260 when there is no supplier, / Cr Cash), which is why
        # the supplier can read negative before delivery -- an advance, and it
        # ties to AP. `order_journal_uid` stays NULL for these orders.
        if amount_paid > _eps:
            # W4a-2 fix: reference = the payment's, as post_supplier_payment does.
            gl.post_po_prepayment(conn, cid, branch_id, po_id, bool(supplier_id),
                                  amount_paid, down_pay_uid, currency, reference=down_pay_ref)
        # W4a: queue order + lines in THIS transaction, so the outbox rows and
        # the rows they describe land or roll back together.
        _po_stamp_and_queue_create(cur, po_id, None)
        _audit(conn, 'PO_CREATED', 'purchase_order', po_id, po_number)
        conn.commit()
    except sqlite3.IntegrityError as exc:
        conn.rollback()
        current_app.logger.warning("create_purchase_order failed on a database constraint: %s", exc)
        return jsonify({
            'status': 'error',
            'message': 'This purchase order could not be created because of a conflicting record. Please try again.',
        }), 409
    except sqlite3.DatabaseError as exc:
        conn.rollback()
        current_app.logger.exception("create_purchase_order failed: %s", exc)
        return jsonify({'status': 'error', 'message': 'Could not create this purchase order.'}), 400
    finally:
        conn.close()
    _sync_nudge()  # best-effort immediate push -- see commercial_runtime/sync/sync_service.py (W4a: the PO, its lines and any down-payment are queued)
    return jsonify({'status': 'success', 'data': {'id': po_id, 'po_number': po_number, 'payment_status': payment_status}})

@retail_bp.route('/purchase-orders/<int:po_id>', methods=['GET'])
@mt_login_required
@mt_require_subsystem('retail')
def get_purchase_order(po_id):
    cid = _cid()
    conn = get_retail_conn()
    # Cross-tenant leak fix, 2026-08-29: same join-condition fix (and same
    # reasoning) as list_purchase_orders's identical comment above -- the
    # company condition belongs on the JOIN, not the WHERE, or a
    # supplier-less PO (a legitimate row) would 404 here instead of
    # returning with a blank supplier_name.
    po   = conn.execute("SELECT po.*,s.name as supplier_name FROM purchase_orders po LEFT JOIN suppliers s ON po.supplier_id=s.id AND s.company_id=po.company_id WHERE po.id=? AND po.company_id=?", (po_id, cid)).fetchone()
    if not po:
        conn.close(); return jsonify({'status': 'error', 'message': 'Not found'}), 404
    items = conn.execute("""
        SELECT poi.*, p.name as product_name, p.sku
        FROM purchase_order_items poi LEFT JOIN products p ON poi.product_id=p.id
        WHERE poi.po_id=?
    """, (po_id,)).fetchall()
    conn.close()
    return jsonify({'status': 'success', 'data': {'po': dict(po), 'items': [dict(i) for i in items]}})

def _is_device_behind_on_sync():
    """True only when sync is CONFIGURED for this device AND this device is
    behind `_SYNC_STALE_THRESHOLD_SECONDS`. Launch-readiness Phase 7 stage
    7c-i (docs/launch-readiness/phase7-offline-ux.md, "DO block: receiving
    a purchase order"): the ONLY caller today is receive_purchase_order's
    guard below, but this is factored out as its own predicate because the
    two silence rules it enforces are not specific to that one route.

    Reached through the SAME module-level seam sync_health() itself uses
    (`_sync_get_active_health()`, imported at the top of this file) --
    never by reaching into app.py's own `_sync_service` variable, which
    would bypass the exact "configured vs not" distinction this function
    exists to make.

    Both silence rules from stage 7b apply here too, and matter MORE here
    because this one refuses work rather than merely rendering a banner:

      * `configured is False` -> never behind. Most installs never turn
        sync on (SYNC_RELAY_BASE_URL unset) and Android's SyncCoordinator
        owns its own loop -- neither has a second device to double-receive
        with, so there is nothing this guard would protect.
      * `never_synced is True` -> never behind. A device that has not
        completed a first sync has no basis for claiming it has drifted;
        there is nothing to have drifted FROM yet.
    """
    health = _sync_get_active_health()
    if not health.get('configured'):
        return False
    if health.get('never_synced'):
        return False
    secs = health.get('seconds_since_last_success')
    return isinstance(secs, (int, float)) and secs > _SYNC_STALE_THRESHOLD_SECONDS


def _evaluate_offline_sales_stop():
    """Launch-readiness Phase 7 stage 7c-ii (docs/launch-readiness/
    phase7-offline-ux.md "Decision 2"; ROADMAP.md's 2026-08-28 "retail
    schema v19" entry): the 72-hour hard stop on NEW SALES, behind a
    manager override -- the last behavioural piece of Phase 7, and "the
    only change in the whole programme that can refuse a sale" (this
    stage's own design note).

    Returns `(blocked, health)` rather than a bare bool: `create_sale`'s
    refusal message must state BOTH facts Decision 2 requires -- how long
    this device has been behind, and how many events are unsent -- and
    both live in the SAME `get_active_health()` snapshot this function
    already had to read to decide `blocked` in the first place. A second,
    separate call from the route to build the message could observe a
    different instant (a background timer tick landing in between) and
    describe a refusal that no longer matches the one just issued.

    Reached through the SAME module-level seam `_is_device_behind_on_sync`
    above already uses -- never a second sync service reference -- and it
    is a BLOCK, not the PO-receipt route's guard: the 30-minute
    `_SYNC_STALE_THRESHOLD_SECONDS` above governs a different, narrower
    hazard (this device cannot see a receipt already applied elsewhere);
    this one governs `_SYNC_SALES_STOP_THRESHOLD_SECONDS` (72 hours), a
    separate, wider constant on purpose -- see that constant's own comment
    in sync_service.py for why the two must never be collapsed into one.

    An install is blocked if and only if ALL of:
      * sync is CONFIGURED for this device;
      * this device HAS synced before (`never_synced` is False);
      * it has been behind by more than `_SYNC_SALES_STOP_THRESHOLD_SECONDS`;
      * there is NO valid manager override recorded
        (`health['offline_override_valid']`, computed by SyncService's own
        `_offline_override_valid` -- Step 2's "validated by comparison,
        never by expiry" rule).

    The first two are the SAME two silence rules `_is_device_behind_on_sync`
    already enforces, and they matter MOST here of anywhere in this file:
    most installs never turn sync on, and blocking their sales would be
    catastrophic and completely unjustified -- they have no second device
    to be out of step with, so `configured is False` must never block.
    A device that has never completed a first sync has no basis for
    claiming it has drifted, so `never_synced is True` must never block
    either -- collapsing that into "behind by a huge number" would trip
    this stop on a shop's very first day, before it has done anything
    wrong (the exact trap `get_health()`'s own `never_synced` field exists
    to prevent, stage 7a).
    """
    health = _sync_get_active_health()
    if not health.get('configured'):
        return False, health
    if health.get('never_synced'):
        return False, health
    secs = health.get('seconds_since_last_success')
    if not (isinstance(secs, (int, float)) and secs > _SYNC_SALES_STOP_THRESHOLD_SECONDS):
        return False, health
    if health.get('offline_override_valid'):
        return False, health
    return True, health


@retail_bp.route('/purchase-orders/<int:po_id>/receive', methods=['POST'])
@mt_login_required
@mt_require_subsystem('retail')
@require_license_capability("retail.purchase.create", restricted_mode_allowlist=RETAIL_RESTRICTED_ALLOWLIST)
@mt_require_capability(CAP_STOCK_ADJUST)
def receive_purchase_order(po_id):
    """Mark PO as received and add stock to inventory.

    Stock-accuracy sweep -- this was a textbook check-then-act race, and
    the single most damaging one in this file. The "already received?"
    test read the PO on a connection holding no write lock, and the final
    `UPDATE purchase_orders SET status='received'` carried no status guard
    of its own. Two requests that both read 'pending' -- a double-clicked
    Receive button, or two devices against the same shared database --
    therefore BOTH walked the item loop and BOTH added the PO's
    quantities. A 10-unit PO landed as 20 units on hand plus two
    'purchase_in' ledger rows, and nothing anywhere reported it: the
    ledger and the balance still agreed with each other, they just both
    agreed on a number twice the size of the delivery.

    Fixed with the pattern create_sale already proves out below rather
    than a new one:

      * BEGIN IMMEDIATE takes SQLite's write lock BEFORE the PO row is
        read, so a second request blocks at the very top and only gets to
        read the status once the first has committed -- by which point it
        is 'received' and the second exits 409 having written nothing.
      * The status UPDATE additionally carries `AND status<>'received'`
        and its rowcount is checked. Belt and braces: even a future caller
        that somehow reaches this code without the lock still cannot
        double-apply, because the row it needs to flip is no longer there
        to flip.

    Launch-readiness Phase 7 stage 7c-i added a SECOND, wider guard in front
    of both of the above: `status='pending'` is read from THIS device's own
    database, and PO status is never synced (multi-device-design.md §8
    keeps it deliberately device-local), so -- the stage's reasoning went --
    the two guards above cannot see a receipt already applied by a
    DIFFERENT device, and two devices whose users both hold
    `retail.stock.adjust` could each receive the same PO once each, with
    both additive `purchase_in` movements surviving the sync merge, so the
    delivery would be double-counted. `_is_device_behind_on_sync()` blocked
    receipt whenever this device was behind, as the one case that hazard
    was thought to be preventable in.

    RETRACTED (2026-08-29), then SUPERSEDED (W4a, schema v45). That 2026-08-29
    retraction was right for its day -- `purchase_orders` was local-only, a PO
    existed on exactly ONE device, so there was no second copy to double-
    receive on, and blocking receipt whenever this device was behind on sync
    stopped a shop booking in a delivery that had physically arrived. The
    stale-device guard stays removed. But since W4a the order DOES sync, so
    the hazard exists in a different shape: two computers can each receive the
    same order while offline. The answer is not a "behind on sync" refusal; it
    is that the receipt cannot count twice:

      * the movement uid is DETERMINISTIC (po_core.receipt_movement_uid of
        order uid + line uid), so two computers that each receive mint the
        SAME uid and the second insert collides on the unique index;
      * the movement is inserted FIRST with ON CONFLICT(uid) DO NOTHING and
        the stock/avg-cost updates run only when `rowcount == 1`. When the
        other computer's identical receipt is already here (its movement
        arrived by sync, and the sync apply added the stock), this one adds
        nothing and queues nothing -- stock moves once, everywhere;
      * a PO that arrived here before its order JOURNAL did (`order_journal_
        uid` names a journal this computer does not hold) is refused with 409
        PO_BOOKS_NOT_ARRIVED, because posting the 1260 -> 1200 receipt without
        the order it moves would book a receipt against nothing.

    `_is_device_behind_on_sync()` itself is untouched and still guards
    create_sale's stage 7d-iii oversell relaxation.

    BEGIN IMMEDIATE plus the conditional `status NOT IN ('received',
    'cancelled')` UPDATE still stop the same-database race (a double-clicked
    Receive button). Two computers receiving offline and then syncing both end
    up 'received' (the status merge is forward-only, see po_core.
    PO_STATUS_RANK) with the stock added once.

    W4a-2 (schema v46) -- PARTIAL RECEIVE, AND DEBT AT DELIVERY. This route no
    longer flips an order to 'received'. It records one RECEIPT: an immutable,
    synced fact (header + one line per product delivered) that says how much of
    each line arrived. `received_qty`, the order's status and the supplier's
    debt are all DERIVED from the receipts (po_core.recompute_po_receive_state),
    so a short delivery is recorded as short instead of being refused or booked
    as complete. Body (all optional): {"lines":[{"item_id"|"item_uid", "quantity"}]};
    no body receives every line's REMAINING quantity (older desktop/phone
    builds keep working). Books: the writer posts the receipt's own journal
    (gl.post_po_receipt_for); peers get it by sync and post nothing.
    """
    cid  = _cid()
    conn = get_retail_conn()
    try:
        conn.execute("BEGIN IMMEDIATE")
        cur = conn.cursor()
        po  = cur.execute("SELECT * FROM purchase_orders WHERE id=? AND company_id=?", (po_id, cid)).fetchone()
        if not po:
            conn.rollback()
            return jsonify({'status': 'error', 'message': 'PO not found'}), 404
        body = request.get_json(silent=True)
        body = body if isinstance(body, dict) else {}
        # W4a-2 verify R1: the client's key for THIS delivery (minted when the
        # dialog opened). A retry / double Enter / double click carries the same
        # key and so the same receipt uid -- answered here, BEFORE any guard that
        # depends on what is left to receive, so a retry of a delivery that has
        # since been followed by another still reads "already recorded" instead
        # of a confusing OVER_RECEIPT. No key = no retry dedupe (see below).
        receipt_key = body.get('receipt_key')
        if receipt_key is not None and not po_core.valid_receipt_key(receipt_key):
            conn.rollback()
            return jsonify({'status': 'error', 'code': 'BAD_RECEIPT_KEY',
                            'message': 'receipt_key must be 8 to 64 letters, digits or dashes.'}), 400
        if receipt_key is not None and po['uid']:
            keyed_uid = po_core.keyed_receipt_uid(po['uid'], receipt_key)
            if cur.execute("SELECT 1 FROM purchase_order_receipts WHERE company_id=? AND uid=?",
                           (cid, keyed_uid)).fetchone():
                conn.rollback()
                return jsonify({'status': 'success', 'already_recorded': True,
                                'data': {'receipt_uid': keyed_uid}}), 200
        if po['status'] == 'received':
            conn.rollback()
            return jsonify({'status': 'error', 'message': 'PO already received'}), 409
        # STOCK-BOOKS B2: a CANCELLED order's goods were never coming -- its
        # order journal has been reversed, so receiving it would put stock on
        # the shelves with no books entry behind it. This test used to read
        # only 'received', which is exactly what let a cancelled PO be received.
        if po['status'] == 'cancelled':
            conn.rollback()
            return jsonify({'status': 'error', 'message': 'PO is cancelled and cannot be received'}), 409
        # W4a-2: closed short = the supplier will not send the rest; nothing more
        # can be received against it.
        if po['status'] == 'closed':
            conn.rollback()
            return jsonify({'status': 'error', 'message': 'PO is closed and cannot be received'}), 409
        ap_basis = po['ap_basis'] or 'order'
        # W4a: this order reached us by sync but the journal it posted has not
        # (events are applied in batches and a journal can park). Receiving now
        # would book Dr 1200 / Cr 1260 against an order this computer has never
        # seen -- refuse, write nothing, and let a later sync make it possible.
        # W4a-2: only an 'order'-basis PO HAS an order journal to wait for; a
        # 'receipt'-basis one posts nothing until now.
        if (ap_basis == 'order' and po['order_journal_uid']
                and gl.po_order_journal_missing(conn, cid, po['order_journal_uid'])):
            conn.rollback()
            return jsonify({'status': 'error', 'code': 'PO_BOOKS_NOT_ARRIVED',
                            'message': "This order's bookkeeping has not reached this computer yet. "
                                       "Sync, then try again."}), 409

        items = cur.execute("SELECT * FROM purchase_order_items WHERE po_id=? ORDER BY id", (po_id,)).fetchall()
        # W4a verify F1: the header and its order journal can both be here while
        # a LINE is still parked (its product has not synced). Receiving then
        # moves the books for the whole order (1260 -> 1200 at the full
        # amount) but the stock for only the lines present -- ledger and shelves
        # silently disagree, and the missing line's stock can never be added
        # afterwards because the order is already 'received'. Refuse, write
        # nothing; a later sync brings the line and the same click then works.
        # `item_count` NULL means the writer predates this check (or never sent
        # it): no count to compare, so the OLD behaviour stands -- refusing
        # would strand every pre-W4a order.
        if po['item_count'] is not None and len(items) < po['item_count']:
            conn.rollback()
            return jsonify({'status': 'error', 'code': 'PO_LINES_NOT_ARRIVED',
                            'message': "Some lines of this order have not reached this computer yet. "
                                       "Sync, then try again."}), 409
        # W4a-2: the same hazard one level down. A receipt header can be here
        # with some of its lines still parked; "what is already received" would
        # then read short and this receipt would take stock for quantity another
        # computer already took. Refuse until every local receipt is complete.
        recv_rows = cur.execute(
            "SELECT id, uid, line_count FROM purchase_order_receipts WHERE company_id=? AND po_id=? ORDER BY id",
            (cid, po_id)).fetchall()
        for rr in recv_rows:
            have = cur.execute("SELECT COUNT(*) FROM purchase_order_receipt_lines WHERE receipt_id=?",
                               (rr['id'],)).fetchone()[0]
            if rr['line_count'] is not None and have < rr['line_count']:
                conn.rollback()
                return jsonify({'status': 'error', 'code': 'PO_RECEIPTS_NOT_ARRIVED',
                                'message': "Part of an earlier delivery has not reached this computer yet. "
                                           "Sync, then try again."}), 409
        # Quantity already received per line, from the receipts themselves (the
        # `received_qty` column is only their cache). W4a-2 verify R2: summed in
        # DECIMAL by the core (po_core.received_by_item), not by a float SQL SUM --
        # 1 - (0.1 + 0.2) is 0.69999... in floats, which refused the last 0.7 of
        # a fractional order as OVER_RECEIPT and left it unfinishable.
        got = po_core.received_by_item(conn, cid, po_id)
        remaining = {it['id']: Decimal(str(it['quantity'] or 0)) - got.get(it['id'], Decimal('0'))
                     for it in items}
        req_lines = body.get('lines')
        selected = []          # [(item row, Decimal quantity)]
        if req_lines:
            if not isinstance(req_lines, list):
                conn.rollback()
                return jsonify({'status': 'error', 'message': 'lines must be a list'}), 400
            asked = {}
            for rl in req_lines:
                rl = rl if isinstance(rl, dict) else {}
                match = next((it for it in items
                              if (rl.get('item_id') is not None and it['id'] == rl.get('item_id'))
                              or (rl.get('item_uid') and it['uid'] == rl.get('item_uid'))), None)
                try:
                    q = Decimal(str(rl.get('quantity')))
                except Exception:  # noqa: BLE001 -- any unparsable quantity is a 400
                    q = Decimal('0')
                if match is None or not q.is_finite() or q <= 0:
                    conn.rollback()
                    return jsonify({'status': 'error',
                                    'message': 'Each line needs a known item and a quantity above zero.'}), 400
                asked[match['id']] = asked.get(match['id'], Decimal('0')) + q
            for it in items:
                if it['id'] in asked:
                    if asked[it['id']] > remaining[it['id']]:
                        pname = cur.execute("SELECT name FROM products WHERE id=? AND company_id=?",
                                            (it['product_id'], cid)).fetchone()
                        conn.rollback()
                        return jsonify({'status': 'error', 'code': 'OVER_RECEIPT',
                                        'message': f"Only {remaining[it['id']].normalize():f} of "
                                                   f"{(pname['name'] if pname else 'this item')} "
                                                   f"is still to receive."}), 409
                    selected.append((it, asked[it['id']]))
        else:
            selected = [(it, remaining[it['id']]) for it in items if remaining[it['id']] > 0]
        if not selected:
            conn.rollback()
            return jsonify({'status': 'error', 'message': 'PO already received'}), 409
        # `po['branch_id']` is a trusted value from THIS company's own PO row
        # (fetched WHERE company_id=? above) -- always set for a PO created
        # after this fix (create_purchase_order now resolves one via
        # _resolve_working_branch), so this fallback exists only for
        # legacy/pre-migration rows with a NULL branch_id. Launch-readiness
        # chain wave C1: that fallback is now pin-aware too, same reasoning
        # as every other _default_branch call site in this file.
        bid   = po['branch_id'] or _resolve_working_branch(conn, cid)[0]
        # v13 stamp, resolved once for the whole receipt: every line of one
        # delivery was received by one person at one terminal at one moment,
        # and re-resolving per line would let them claim otherwise.
        actor, terminal, utc_now = _stamp()
        # Resolved once for the whole receipt, same reasoning as `actor,
        # terminal, utc_now` on the line above -- every line of one delivery
        # was received at the SAME branch.
        receipt_branch_uid = _branch_uid(conn, bid)
        # Schema v39 (cost basis for COGS): drives the quantization of the
        # moving-average update below, same `currency` every money figure in
        # this file is quantized at -- see `_money`'s own docstring.
        currency = _company_currency(conn, cid)
        received_on = datetime.now().strftime('%Y-%m-%d')
        # W4a-2 verify R1: the receipt's identity (replaces the D4 count-based
        # rule, which was wrong both ways -- see po_core.completing_receipt_uid).
        #   * the receipt that COMPLETES the order: uuid5 of the history it
        #     completes (order uid + the receipts present here), so two computers
        #     that saw the same receipts and both receive "the rest" collapse to
        #     one fact, and ones with different histories stay two (flagged
        #     po_over_received by the sync apply) -- never silently lost;
        #   * a PARTIAL receipt: uuid5 of the client's receipt_key, so a retry /
        #     double submit hits ON CONFLICT(uid) and is recorded once;
        #   * a partial with NO key (an older client): a random uuid4. There is
        #     nothing to say two requests are the same delivery, and a
        #     deterministic uid would merge two real deliveries of one size.
        # The VALUE is computed here once and synced as a fact -- a peer never
        # recomputes it.
        completing = po_core.receipt_completes(conn, cid, po_id, [(it['id'], q) for it, q in selected])
        if not (po['uid'] and all(it['uid'] for it, _q in selected)):
            recv_uid = _new_uid()
        elif completing:
            recv_uid = po_core.completing_receipt_uid(po['uid'], [rr['uid'] for rr in recv_rows])
        elif receipt_key is not None:
            recv_uid = po_core.keyed_receipt_uid(po['uid'], receipt_key)
        else:
            recv_uid = _new_uid()
        recv_value = po_core.receipt_value(conn, cid, po_id, [(it['id'], q) for it, q in selected], currency)
        hdr = cur.execute(
            "INSERT INTO purchase_order_receipts (company_id,uid,po_id,branch_id,received_at,value,line_count,"
            "legacy,created_by,actor_user_uid,terminal_id,created_at_utc) VALUES (?,?,?,?,?,?,?,0,?,?,?,?) "
            "ON CONFLICT(uid) DO NOTHING",
            (cid, recv_uid, po_id, bid, received_on, float(recv_value), len(selected), _uid(), actor, terminal, utc_now))
        if hdr.rowcount == 0:
            # A sibling already recorded exactly this delivery (its header is
            # here). Writing anything more would count it twice.
            conn.rollback()
            return jsonify({'status': 'success', 'already_recorded': True,
                            'data': {'receipt_uid': recv_uid}}), 200
        recv_id = hdr.lastrowid
        recv_line_events = []
        for item, dqty in selected:
            qty = float(dqty)
            line_uid = (po_core.receipt_line_uid(recv_uid, item['uid']) if item['uid'] else _new_uid())
            # W4a: the receipt's movement is written FIRST, under a uid that is
            # a pure function of (order uid, line uid) -- the same on every
            # computer. `ON CONFLICT(uid) WHERE uid IS NOT NULL DO NOTHING`
            # repeats the partial unique index's predicate exactly as
            # sync_service.py's inventory_movement apply does (SQLite refuses
            # the conflict target otherwise). `rowcount == 0` means another
            # computer's identical receipt has ALREADY put this stock here (its
            # movement arrived by sync, and the apply added the quantity), so
            # this receipt must add NOTHING: no balance bump, no avg-cost
            # blend, no queued event -- the stock moves once, everywhere. Only
            # the line's `received_qty` is stamped (it is a fact about the
            # order, true either way). Skipping this gate doubles the stock,
            # silently, with ledger and balance still agreeing on the doubled
            # number -- the failure retail_po_sync_routes_test.py R4 pins.
            #
            # A line with no uid cannot exist after v45 (every row is stamped);
            # the fallback keeps a hand-built fixture working but then offers no
            # cross-computer protection for that line, as before.
            # W4a-2: the movement uid now names the RECEIPT line (it used to name
            # the order line, which allowed one receipt per line per order).
            movement_uid = (po_core.receipt_line_movement_uid(recv_uid, item['uid'])
                            if item['uid'] else _new_uid())
            cur.execute(
                "INSERT INTO purchase_order_receipt_lines (receipt_id,uid,po_item_id,quantity,movement_uid) "
                "VALUES (?,?,?,?,?)", (recv_id, line_uid, item['id'], qty, movement_uid))
            recv_line_events.append((line_uid, item['uid'], qty, movement_uid))
            ins = cur.execute("""
                INSERT INTO inventory_movements (company_id,product_id,branch_id,movement_type,quantity,unit_cost,reference,created_by,
                                                 uid,actor_user_uid,terminal_id,created_at_utc)
                VALUES (?,?,?,'purchase_in',?,?,?,?,?,?,?,?)
                ON CONFLICT(uid) WHERE uid IS NOT NULL DO NOTHING
            """, (cid, item['product_id'], bid, qty, item['unit_cost'], po['po_number'], _uid(),
                  movement_uid, actor, terminal, utc_now))
            if ins.rowcount == 0:
                continue          # the stock for this line is already here (see above)
            # Schema v39: maintain `products.avg_cost` as a MOVING WEIGHTED
            # AVERAGE at the moment stock actually arrives -- see database/
            # schema.py's v39 migration docstring for why a weighted average
            # rather than FIFO, and why `cost_price` itself is NEVER touched
            # here: it stays the shopkeeper's own manually-typed field, and
            # `avg_cost` is the only cost figure this route writes.
            #
            # `qty_on_hand` is read COMPANY-WIDE (summed across every
            # branch), never scoped to this receipt's own `bid` -- `products.
            # avg_cost` is a single company-scoped column (`products` has no
            # branch_id of its own), so the average must be weighted by the
            # SAME scope it lives at. This mirrors metrics.py's `inventory_
            # value`, which sums `inventory_balances` company-wide rather
            # than per branch for the identical reason.
            #
            # Read BEFORE this item's own `inventory_balances` UPDATE two
            # lines below moves the figure: the formula weights the stock
            # that was ALREADY on hand against the stock arriving now, so
            # reading it after would double-count this receipt's own
            # quantity into both halves of the average.
            on_hand_row = cur.execute(
                "SELECT COALESCE(SUM(quantity_on_hand),0) FROM inventory_balances "
                "WHERE company_id=? AND product_id=?",
                (cid, item['product_id'])
            ).fetchone()
            qty_on_hand = float(on_hand_row[0] or 0)
            old_avg_row = cur.execute(
                "SELECT avg_cost FROM products WHERE id=? AND company_id=?",
                (item['product_id'], cid)
            ).fetchone()
            old_avg = float(old_avg_row['avg_cost'] or 0) if old_avg_row else 0.0
            denom = qty_on_hand + float(qty)
            # Guard the zero/negative denominator. The common case this
            # reaches is a product that has never been stocked before AND
            # carries no `inventory_balances` row yet (`qty_on_hand == 0`),
            # where the formula below collapses to exactly `unit_cost` --
            # "the first receipt simply sets the average to the received
            # cost" the task's own spec calls for, no special-casing needed.
            # `denom <= 0` is reachable only through a corrupted/negative
            # on-hand figure this route did not cause; keeping the OLD
            # average rather than dividing by zero refuses to compound a
            # pre-existing data problem into the cost ledger too.
            if denom > 0:
                new_avg = (
                    Decimal(str(qty_on_hand)) * Decimal(str(old_avg))
                    + Decimal(str(qty)) * Decimal(str(item['unit_cost']))
                ) / Decimal(str(denom))
                # AUDIT (2026-09-21, adversarial cost-basis pass): the guard
                # immediately above only catches a zero/negative DENOMINATOR.
                # A NEGATIVE NUMERATOR reaching a POSITIVE denominator slips
                # straight through it. `qty_on_hand` is summed COMPANY-WIDE
                # (see the read above) and can be legitimately negative --
                # create_sale's `behind_on_sync` oversell path lets a device
                # sell stock it has not yet learned about from a peer, which
                # can drive this company's on-hand total below zero without
                # THIS receipt having done anything wrong. When that happens,
                # `old_avg` gets weighted by a negative quantity and the
                # formula can swing past zero even though `item['unit_cost']`
                # -- the price actually paid on THIS transaction -- is an
                # ordinary positive number.
                #
                # Reproduced live: old_avg=10, qty_on_hand=-5, receive 6 @
                # 5.00 -> formula gives -20.00. Left uncaught, that negative
                # figure was PERSISTED straight into products.avg_cost and
                # then SNAPSHOTTED by the very next sale into sale_items.
                # unit_cost -- a shopkeeper sees a negative cost on a real
                # sale and nothing complains, because the negative total
                # quietly fails post_cogs's own epsilon gate ("is there a
                # real cost basis here") instead of raising anywhere loud
                # enough to notice.
                #
                # Fall back to `item['unit_cost']` here, NOT 0. This file's
                # cost model treats 0 as ITS OWN sentinel for "no cost basis
                # known at all" (metrics.py falls back to cost_price when
                # avg_cost is 0; post_cogs posts nothing for a 0 total) --
                # clamping a negative result to 0 would misreport a product
                # that DOES have a known cost (the price just paid on this
                # very receipt) as one that has none. `item['unit_cost']` is
                # the one number in this formula that is an OBSERVED fact of
                # this transaction rather than a figure dragged along by a
                # corrupted running total -- the honest answer, not merely a
                # safe one, the same reasoning the `denom <= 0` branch above
                # (untouched by this fix) already applies to a different
                # corruption of this same running total.
                if new_avg < 0:
                    new_avg = Decimal(str(item['unit_cost']))
                new_avg_cost = _money(new_avg, currency)
                # Sync-payload coverage follow-up (2026-09-21): row_version/
                # updated_at_utc now bump in the SAME statement as the field
                # write, matching update_product's own "every successful
                # write to a synced column bumps row_version" rule (see that
                # route's own comment). Without this, the `product`/`update`
                # event queued below would carry the SAME row_version a peer
                # that already knows this product is very likely already
                # holding, and sync_service.py's product apply branch gates
                # its DO UPDATE on `excluded.row_version > products.
                # row_version` -- an unchanged row_version there is
                # indistinguishable from a stale replay and gets silently
                # discarded into sync_conflicts instead of applied,
                # defeating the point of queuing the event at all.
                cur.execute(
                    "UPDATE products SET avg_cost=?, row_version=row_version+1, updated_at_utc=? "
                    "WHERE id=? AND company_id=?",
                    (new_avg_cost, utc_now, item['product_id'], cid)
                )
                # AUDIT (2026-09-21): this route used to update products.
                # avg_cost with NO matching sync event at all -- the sync_
                # outbox row count for entity_type='product' was measured
                # unchanged before and after a receipt. A peer device
                # therefore never learned the new average; only a LATER,
                # unrelated PATCH to this same product (update_product's own
                # `product`/`update` event, which re-reads the full row)
                # would ever carry the real figure across the wire. Note for
                # the next reader: retail_sync_payload_coverage_test.py's
                # own ratchet did NOT catch this -- it checks that a payload
                # DICT contains every column, never that an event is ever
                # EMITTED, and a payload this route never queued has no call
                # site for that ratchet to inspect in the first place.
                #
                # Matches update_product's own emission mechanism exactly: a
                # full-row re-read (the INSERT half of the receiving
                # device's upsert needs a complete snapshot for a device
                # seeing this id for the first time) merged with `_changed_
                # fields` naming only the column THIS write actually
                # touched. `avg_cost` is the ONLY thing a receipt ever
                # changes on `products` -- `cost_price` stays manual-entry-
                # only, per this loop's own comment above -- so `_changed_
                # fields` here is always exactly `['avg_cost']`, never
                # `sorted(fields)` the way update_product computes it: there
                # is no `fields` dict on this route, this write touches one
                # column, unconditionally, every time this branch runs.
                #
                # Emitted only when the average actually MOVED, compared
                # against the currency's own epsilon (never a hardcoded
                # 0.005 -- see `_money_epsilon`'s own docstring): a second
                # receipt landing at EXACTLY the prior average (most
                # commonly, a second delivery at an identical price) would
                # otherwise queue an outbox row that carries no new
                # information for any peer to apply.
                if abs(new_avg_cost - old_avg) > _money_epsilon(currency):
                    product_row = cur.execute(
                        "SELECT sku,barcode,name,category_id,supplier_id,cost_price,sell_price,tax_rate,unit,"
                        "reorder_level,reorder_method,status,deleted_at_utc,parent_product_id,variant_label,avg_cost,"
                        "row_version,updated_at_utc FROM products WHERE id=?", (item['product_id'],)
                    ).fetchone()
                    _queue_sync_event(cur, 'product', item['product_id'], 'update',
                                       dict(product_row) | {'id': item['product_id'],
                                                             '_changed_fields': ['avg_cost']})

            # Schema v40 (per-branch cost basis): maintain `inventory_
            # balances.avg_cost` as its OWN moving weighted average, scoped
            # to (product_id, branch_id) -- see database/schema.py's v40
            # migration docstring for why this lives on `inventory_balances`
            # rather than a new table, and ROADMAP.md's v40 entry for why a
            # company-wide figure alone is wrong for a multi-branch shop.
            #
            # Weighted by THIS BRANCH's own `quantity_on_hand`, never the
            # company-wide sum the block above reads -- a receipt at an
            # empty second branch must not appear to widen an average a busy
            # first branch already built. Read BEFORE the INSERT OR IGNORE/
            # UPDATE below moves the figure, identical "read before this
            # item's own write" ordering the company-wide block above
            # already follows, for the identical reason.
            branch_bal_row = cur.execute(
                "SELECT quantity_on_hand, avg_cost FROM inventory_balances "
                "WHERE company_id=? AND product_id=? AND branch_id=?",
                (cid, item['product_id'], bid)
            ).fetchone()
            branch_qty_on_hand = float(branch_bal_row['quantity_on_hand']) if branch_bal_row else 0.0
            branch_old_avg = float(branch_bal_row['avg_cost'] or 0) if branch_bal_row else 0.0
            # STOCK-BOOKS verify F1: the blend is the ONE shared rule
            # (commercial_runtime/stock_cost.py) every writer and the sync
            # apply use -- free/negative prior stock takes the incoming cost.
            branch_denom = branch_qty_on_hand + float(qty)
            # Same zero/negative-denominator and negative-numerator guards
            # as the company-wide block above, applied per branch -- see
            # that block's own AUDIT comment (2026-09-21) for the full
            # "old_avg gets weighted by a negative quantity" reasoning this
            # mirrors. `behind_on_sync` oversells are recorded against a
            # branch's own balance (create_sale's `on_hand` read is already
            # branch-scoped), so the same corruption this guards against
            # company-wide can equally happen to a single branch.
            branch_new_avg_cost = _money(_blended_unit_cost(
                branch_qty_on_hand, branch_old_avg, qty, item['unit_cost']), currency)

            cur.execute("""
                INSERT OR IGNORE INTO inventory_balances (company_id,product_id,branch_id,quantity_on_hand)
                VALUES (?,?,?,0)
            """, (cid, item['product_id'], bid))
            cur.execute("""
                UPDATE inventory_balances SET quantity_on_hand = quantity_on_hand + ?, avg_cost = ?
                WHERE company_id=? AND product_id=? AND branch_id=?
            """, (qty, branch_new_avg_cost, cid, item['product_id'], bid))
            # (The movement row itself was inserted at the top of this loop
            # body -- W4a. Its sync event is queued here, after the balance
            # it describes has moved, as before.)
            # Wave B: queue the matching sync event -- see create_sale's own
            # inventory_movement emission for the shape every writer shares.
            _queue_sync_event(cur, 'inventory_movement', movement_uid, 'create', {
                'uid': movement_uid, 'product_id': item['product_id'], 'branch_id': bid,
                'branch_uid': receipt_branch_uid,
                'movement_type': 'purchase_in', 'quantity': qty, 'unit_cost': item['unit_cost'],
                'reference': po['po_number'], 'notes': None, 'created_by': _uid(),
                'actor_user_uid': actor, 'terminal_id': terminal, 'created_at_utc': utc_now,
            })

        # STOCK-BOOKS B1 / W4a-2: goods arrived -- book THIS receipt. 'receipt'
        # basis: Dr Inventory / Cr AP (or Goods Ordered when there is no
        # supplier) for the receipt's value; 'order' basis: move its share of
        # the order's 1260 into Inventory. Same transaction as the stock
        # movements above, so books and shelves cannot part. Peers post nothing:
        # the journal syncs itself.
        gl.post_po_receipt_for(conn, cid, bid, po, recv_uid, recv_value, currency)
        # status / received_qty / received_at are caches of the receipts.
        new_status = po_core.recompute_po_receive_state(conn, cid, po_id)
        if po['supplier_id']:
            _refresh_party_balance(conn, 'suppliers', po['supplier_id'], cid, currency)
        # W4a-2: announce the receipt and its lines (immutable facts; literal
        # dicts for the payload-coverage ratchet). The old `status` update on
        # the order header is gone -- every computer derives status from these.
        _queue_sync_event(cur, 'purchase_order_receipt', recv_uid, 'create', {
            'uid': recv_uid, 'po_uid': po['uid'], 'branch_uid': receipt_branch_uid,
            'received_at': received_on, 'value': float(recv_value), 'line_count': len(selected),
            'created_by': _uid(), 'actor_user_uid': actor, 'terminal_id': terminal,
            'created_at_utc': utc_now})
        for l_uid, l_item_uid, l_qty, l_mov in recv_line_events:
            _queue_sync_event(cur, 'purchase_order_receipt_line', l_uid, 'create', {
                'uid': l_uid, 'receipt_uid': recv_uid, 'po_item_uid': l_item_uid,
                'quantity': l_qty, 'movement_uid': l_mov})
        _audit(conn, 'PO_RECEIVED', 'purchase_order', po_id, po['po_number'])
        conn.commit()
    except sqlite3.DatabaseError as exc:
        conn.rollback()
        current_app.logger.exception("receive_purchase_order(%s) failed: %s", po_id, exc)
        return jsonify({'status': 'error', 'message': 'Could not receive this purchase order.'}), 400
    finally:
        conn.close()
    _emit('StockReceived', {'po_id': po_id, 'po_number': po['po_number']})
    _sync_nudge()  # W4a-2: the receipt and its lines are queued
    return jsonify({'status': 'success', 'data': {'receipt_uid': recv_uid, 'status': new_status,
                                                  'value': float(recv_value)}})


#: the note accept_reorder_request writes on the PO it drafts; cancel_purchase_order
#: reads the request id back out of it (STOCK-BOOKS verify F7).
_REORDER_PO_NOTE_PREFIX = 'Auto-drafted from reorder request '


@retail_bp.route('/purchase-orders/<int:po_id>/cancel', methods=['POST'])
@mt_login_required
@mt_require_subsystem('retail')
@require_license_capability("retail.purchase.create", restricted_mode_allowlist=RETAIL_RESTRICTED_ALLOWLIST)
@mt_require_capability(CAP_STOCK_ADJUST)
def cancel_purchase_order(po_id):
    """STOCK-BOOKS B2: cancel a purchase order that has not been received.

    Before this route a wrong order could never be undone: it sat 'pending' for
    ever, its amount stuck in Goods Ordered (1260) and in what the shop owes the
    supplier. Cancelling reverses the ORDER journal exactly (gl.reverse_journal:
    1260 and AP for a new order, 1200 and AP for a legacy one, and the cash leg
    of a down payment that was already voided), and the PO drops out of the
    supplier's balance, statement and aging (party_balance and the two routes
    filter status='cancelled').

    REFUSED while an ACTIVE payment is tied to the order (409
    PO_HAS_PAYMENTS): the cash that went out must be voided first, otherwise
    cancelling would leave the supplier owing the shop money nobody recorded.
    Also refused when already received or already cancelled. BEGIN IMMEDIATE and
    a status-guarded UPDATE, like receive, so a double click cancels once.
    """
    cid = _cid()
    conn = get_retail_conn()
    try:
        conn.execute("BEGIN IMMEDIATE")
        cur = conn.cursor()
        po = cur.execute("SELECT id, status, po_number, notes, uid, order_journal_uid, ap_basis, closed_at "
                         "FROM purchase_orders WHERE id=? AND company_id=?",
                         (po_id, cid)).fetchone()
        if not po:
            conn.rollback()
            return jsonify({'status': 'error', 'message': 'PO not found'}), 404
        # W4a-2: once any goods have arrived the order cannot be un-ordered --
        # the stock is on the shelves and the debt for it is booked. The way to
        # stop a part-delivered order is "Close short". Checked before the status
        # message so a 'partial' order gets this code, not a generic refusal.
        # Counts the receipt rows themselves too, so a receipt that arrived by
        # sync a moment ago (status cache not yet recomputed) still blocks.
        has_receipts = cur.execute(
            "SELECT COUNT(*) FROM purchase_order_receipts WHERE company_id=? AND po_id=?",
            (cid, po_id)).fetchone()[0]
        if po['status'] == 'partial' or (has_receipts and po['status'] not in ('cancelled',)):
            conn.rollback()
            return jsonify({'status': 'error', 'code': 'PO_HAS_RECEIPTS',
                            'message': 'Part of this order has already been received. '
                                       'Use Close short instead.'}), 409
        if po['status'] in ('received', 'cancelled', 'closed'):
            conn.rollback()
            return jsonify({'status': 'error',
                            'message': f"Cannot cancel a purchase order that is {po['status']}."}), 409
        ap_basis = po['ap_basis'] or 'order'
        # W4a: same guard as receive -- an order that reached this computer
        # before its journal did cannot be reversed here (there is nothing yet
        # to reverse), and cancelling without reversing would strand 1260 and
        # the supplier's debt. Refuse and write nothing.
        if (ap_basis == 'order' and po['order_journal_uid']
                and gl.po_order_journal_missing(conn, cid, po['order_journal_uid'])):
            conn.rollback()
            return jsonify({'status': 'error', 'code': 'PO_BOOKS_NOT_ARRIVED',
                            'message': "This order's bookkeeping has not reached this computer yet. "
                                       "Sync, then try again."}), 409
        paid = cur.execute(
            "SELECT COUNT(*) FROM payments WHERE company_id=? AND related_type='po' AND related_id=? "
            "AND COALESCE(status,'active')='active'", (cid, po_id)).fetchone()[0]
        if paid:
            conn.rollback()
            return jsonify({'status': 'error', 'code': 'PO_HAS_PAYMENTS',
                            'message': 'This order has a payment. Void the payment first.'}), 409
        # W4a-2: cancelling stamps the set-once `cancelled_at`; `status` is the
        # derived cache (po_core.recompute_po_receive_state), the guard being
        # that nothing has arrived (checked above, same transaction).
        cancelled_at = now_utc_iso()
        cur.execute("UPDATE purchase_orders SET cancelled_at=COALESCE(cancelled_at, ?) "
                    "WHERE id=? AND company_id=? AND status NOT IN ('received','cancelled','closed','partial')",
                    (cancelled_at, po_id, cid))
        if cur.rowcount != 1:
            conn.rollback()
            return jsonify({'status': 'error', 'message': 'PO already received or cancelled'}), 409
        po_core.recompute_po_receive_state(conn, cid, po_id)
        # W4a: found by uid when the order names one (works on a computer whose
        # copy of the journal arrived by sync, `source_id` NULL there), by the
        # old source_id lookup for a legacy order. A 'receipt'-basis order
        # posted no order journal, so there is nothing to reverse for it.
        if ap_basis == 'order':
            order = gl.po_order_journal(conn, cid, po_id, order_journal_uid=po['order_journal_uid'])
            if order:
                gl.reverse_journal(conn, cid, order['id'], memo=f"Purchase order {po['po_number']} cancelled")
        # W4a-2: tell the other computers. The header update now carries the
        # set-once timestamps (the receiver keeps the earliest and derives the
        # status itself); it no longer carries a `status` to merge by rank.
        _queue_sync_event(cur, 'purchase_order', po['uid'], 'update', {
            'uid': po['uid'], 'cancelled_at': cancelled_at, 'closed_at': po['closed_at']})
        currency = _company_currency(conn, cid)
        sup = cur.execute("SELECT supplier_id FROM purchase_orders WHERE id=? AND company_id=?",
                          (po_id, cid)).fetchone()
        if sup and sup['supplier_id']:
            _refresh_party_balance(conn, 'suppliers', sup['supplier_id'], cid, currency)
        # STOCK-BOOKS verify F7: a PO drafted by accept_reorder_request leaves its
        # reorder request 'accepted'. The partial unique index
        # idx_reorder_requests_open allows ONE pending-or-accepted request per
        # product, so after the cancel the product could never raise a new request
        # while the stock it needed never arrived. Move that request to 'declined'
        # (the existing terminal status; the index exempts it). The link is the
        # note accept_reorder_request writes on the PO it drafts.
        _rid = None
        _note = po['notes'] or ''
        if _note.startswith(_REORDER_PO_NOTE_PREFIX):
            _rid = _note[len(_REORDER_PO_NOTE_PREFIX):].strip()
        if _rid:
            _req = cur.execute(
                "SELECT * FROM reorder_requests WHERE id=? AND company_id=? AND status='accepted'",
                (_rid, cid)).fetchone()
            if _req:
                _now = datetime.now(timezone.utc).isoformat()
                cur.execute(
                    "UPDATE reorder_requests SET status='declined', resolved_at=?, "
                    "row_version=row_version+1, updated_at_utc=? WHERE id=?", (_now, _now, _rid))
                _rv = cur.execute("SELECT row_version FROM reorder_requests WHERE id=?", (_rid,)).fetchone()
                _queue_sync_event(cur, 'reorder_request', _rid, 'update', {
                    'id': _rid, 'branch_id': _req['branch_id'], 'product_id': _req['product_id'],
                    'status': 'declined', 'draft_message': _req['draft_message'], 'resolved_at': _now,
                    'row_version': _rv['row_version'], 'updated_at_utc': _now,
                    '_changed_fields': ['status', 'resolved_at'],
                })
        _audit(conn, 'PO_CANCELLED', 'purchase_order', po_id, po['po_number'])
        conn.commit()
    except sqlite3.DatabaseError as exc:
        conn.rollback()
        current_app.logger.exception("cancel_purchase_order(%s) failed: %s", po_id, exc)
        return jsonify({'status': 'error', 'message': 'Could not cancel this purchase order.'}), 400
    finally:
        conn.close()
    return jsonify({'status': 'success'})

@retail_bp.route('/purchase-orders/<int:po_id>/close', methods=['POST'])
@mt_login_required
@mt_require_subsystem('retail')
@require_license_capability("retail.purchase.create", restricted_mode_allowlist=RETAIL_RESTRICTED_ALLOWLIST)
@mt_require_capability(CAP_STOCK_ADJUST)
def close_purchase_order_short(po_id):
    """W4a-2: CLOSE SHORT -- the supplier delivered part of an order and will
    not send the rest. Allowed only while the order is 'partial' (something has
    arrived, something is still owed).

    The supplier owes nothing for goods that never came, so the debt for the
    undelivered part must not stay on the books. 'receipt'-basis orders booked
    debt only per receipt, so there is nothing to undo; 'order'-basis (pre-v46)
    orders booked the whole order up front, so the undelivered share is moved
    back out (gl.post_po_close_short). Refused 409 CLOSE_SHORT_NEEDS_SUPPLIER
    when the order has no supplier: its unpaid remainder never reached AP, so
    there is no supplier debt to release and the books would not balance.
    Sets the set-once `closed_at`; status is derived. Same authority as
    receiving (a short delivery is a receiving decision).
    """
    cid = _cid()
    conn = get_retail_conn()
    try:
        conn.execute("BEGIN IMMEDIATE")
        cur = conn.cursor()
        po = cur.execute("SELECT * FROM purchase_orders WHERE id=? AND company_id=?", (po_id, cid)).fetchone()
        if not po:
            conn.rollback()
            return jsonify({'status': 'error', 'message': 'PO not found'}), 404
        if po['status'] != 'partial':
            conn.rollback()
            return jsonify({'status': 'error', 'code': 'CLOSE_SHORT_NOT_PARTIAL',
                            'message': 'Only an order that is partly received can be closed short.'}), 409
        if not po['supplier_id']:
            conn.rollback()
            return jsonify({'status': 'error', 'code': 'CLOSE_SHORT_NEEDS_SUPPLIER',
                            'message': 'Choose the supplier on this order before closing it short.'}), 409
        ap_basis = po['ap_basis'] or 'order'
        if (ap_basis == 'order' and po['order_journal_uid']
                and gl.po_order_journal_missing(conn, cid, po['order_journal_uid'])):
            conn.rollback()
            return jsonify({'status': 'error', 'code': 'PO_BOOKS_NOT_ARRIVED',
                            'message': "This order's bookkeeping has not reached this computer yet. "
                                       "Sync, then try again."}), 409
        # W4a-2 verify R3: the same two arrival guards receive has. Closing
        # decides "what never came" from the lines and receipts HERE; with a line
        # or a receipt's lines still parked, that arithmetic reads short, the
        # close-short journal releases debt for goods that DID arrive, and once
        # 'closed' nothing more can be received to correct it. Refuse, write
        # nothing; a later sync makes the same click work. (`item_count` NULL =
        # an order from a writer that never sent it: nothing to compare.)
        n_items = cur.execute("SELECT COUNT(*) FROM purchase_order_items WHERE po_id=?",
                              (po_id,)).fetchone()[0]
        if po['item_count'] is not None and n_items < po['item_count']:
            conn.rollback()
            return jsonify({'status': 'error', 'code': 'PO_LINES_NOT_ARRIVED',
                            'message': "Some lines of this order have not reached this computer yet. "
                                       "Sync, then try again."}), 409
        for rr in cur.execute(
                "SELECT id, line_count FROM purchase_order_receipts WHERE company_id=? AND po_id=?",
                (cid, po_id)).fetchall():
            have = cur.execute("SELECT COUNT(*) FROM purchase_order_receipt_lines WHERE receipt_id=?",
                               (rr['id'],)).fetchone()[0]
            if rr['line_count'] is not None and have < rr['line_count']:
                conn.rollback()
                return jsonify({'status': 'error', 'code': 'PO_RECEIPTS_NOT_ARRIVED',
                                'message': "Part of an earlier delivery has not reached this computer yet. "
                                           "Sync, then try again."}), 409
        currency = _company_currency(conn, cid)
        closed_at = now_utc_iso()
        cur.execute("UPDATE purchase_orders SET closed_at=COALESCE(closed_at, ?) "
                    "WHERE id=? AND company_id=? AND status='partial'", (closed_at, po_id, cid))
        if cur.rowcount != 1:
            conn.rollback()
            return jsonify({'status': 'error', 'code': 'CLOSE_SHORT_NOT_PARTIAL',
                            'message': 'Only an order that is partly received can be closed short.'}), 409
        po_core.recompute_po_receive_state(conn, cid, po_id)
        # W4a-2 verify R4: a closed order is paid against what ARRIVED, so its
        # payment_status moves the moment it closes.
        po_core.recompute_po_paid(conn, cid, po_id, _money_epsilon(currency))
        if ap_basis == 'order':
            bid = po['branch_id'] or _resolve_working_branch(conn, cid)[0]
            gl.post_po_close_short(conn, cid, bid, po, currency)
        _refresh_party_balance(conn, 'suppliers', po['supplier_id'], cid, currency)
        _queue_sync_event(cur, 'purchase_order', po['uid'], 'update', {
            'uid': po['uid'], 'cancelled_at': po['cancelled_at'], 'closed_at': closed_at})
        _audit(conn, 'PO_CLOSED_SHORT', 'purchase_order', po_id, po['po_number'])
        conn.commit()
    except sqlite3.DatabaseError as exc:
        conn.rollback()
        current_app.logger.exception("close_purchase_order_short(%s) failed: %s", po_id, exc)
        return jsonify({'status': 'error', 'message': 'Could not close this purchase order.'}), 400
    finally:
        conn.close()
    _sync_nudge()
    return jsonify({'status': 'success', 'data': {'status': 'closed'}})


@retail_bp.route('/purchase-orders/split-preview', methods=['POST'])
@mt_login_required
@mt_require_subsystem('retail')
@require_license_capability("retail.purchase.create", restricted_mode_allowlist=RETAIL_RESTRICTED_ALLOWLIST)
# Gated although it writes nothing. It is a POST that reads supplier terms
# and unit costs to plan an order, so it is part of purchasing, and leaving
# the one non-writing POST in the file ungated would mean the guard test has
# to carry an exemption -- and an exemption is a shape the next new route can
# quietly take.
@mt_require_capability(CAP_STOCK_ADJUST)
def preview_po_split():
    """Preview-only: groups a basket into per-supplier slices (Thursday demo,
    Stream B). Computes and returns a SplitResult -- never writes anything to
    the database (no PO/purchase_order_items rows are created here; that
    lands with the routes that persist split_group_id/routing_status etc.
    later this week -- see core/retail/po_split.py's module docstring).

    Guarded with retail.purchase.create even though this route only reads/
    computes: a restricted-mode install should get the same consistent block
    as the real PO-creation route, rather than a preview of an action it
    could never actually take.

    Every product/supplier this route touches is looked up scoped to
    _cid() -- unlike create_purchase_order above (a real, pre-existing bug:
    AUDIT-follow-up, 2026-08-10 -- it never validates that supplier_id or any
    product_id in the request actually belongs to the caller's company,
    so a cross-tenant PO is creatable today). That bug is OUT OF SCOPE for
    this route to fix; this route just must not repeat it.
    """
    data = request.json or {}
    cid  = _cid()
    items = data.get('items') or []
    if not items:
        return jsonify({'status': 'error', 'message': 'At least one item required'}), 400

    conn = get_retail_conn()
    try:
        product_ids = []
        for it in items:
            pid = it.get('product_id')
            if not pid:
                return jsonify({'status': 'error', 'message': 'Every item requires a product_id'}), 400
            product_ids.append(pid)

        # launch-readiness Phase 6 stage 6b-iii-a: `AND deleted_at_utc IS
        # NULL` added -- this is a WRITE gate (it plans a purchase order a
        # caller may go on to actually create), not a display list, so a
        # tombstoned product must fall out of `products_by_id` below and hit
        # the existing "Unknown product_id" 400 exactly like an id that never
        # existed.
        #
        # `status='active'` joins it for the same two-population reason
        # `create_supplier_contact`'s comment (this file) spells out in
        # full -- a legacy-deleted product (`status='inactive'`,
        # `deleted_at_utc` NULL) needs the `status` half to fall out here
        # too, not just the tombstone half.
        placeholders = ','.join('?' * len(product_ids))
        prod_rows = conn.execute(
            f"SELECT id, name, sku, supplier_id, cost_price FROM products "
            f"WHERE company_id=? AND status='active' AND deleted_at_utc IS NULL AND id IN ({placeholders})",
            [cid, *product_ids]
        ).fetchall()
        products_by_id = {r['id']: dict(r) for r in prod_rows}

        basket = []
        supplier_ids = set()
        for it in items:
            pid = it['product_id']
            product = products_by_id.get(pid)
            if not product:
                # Named explicitly, not a generic error -- the caller needs to
                # know WHICH product_id in its basket doesn't belong to it.
                return jsonify({'status': 'error', 'message': f'Unknown product_id: {pid}'}), 400

            try:
                qty = float(it.get('quantity'))
            except (TypeError, ValueError):
                return jsonify({'status': 'error', 'message': f'Invalid quantity for product_id {pid}'}), 400
            if qty <= 0:
                return jsonify({'status': 'error',
                                 'message': f'Quantity must be greater than zero for product_id {pid}'}), 400

            unit_cost = it.get('unit_cost')
            if unit_cost is None:
                unit_cost = product['cost_price']
            else:
                try:
                    unit_cost = float(unit_cost)
                except (TypeError, ValueError):
                    return jsonify({'status': 'error',
                                     'message': f'Invalid unit_cost for product_id {pid}'}), 400

            supplier_id = product['supplier_id']
            if supplier_id:
                supplier_ids.add(supplier_id)
            basket.append({
                'product_id': pid, 'product_name': product['name'], 'sku': product['sku'],
                'supplier_id': supplier_id, 'quantity': qty, 'unit_cost': unit_cost,
            })

        suppliers_by_id = {}
        contacts_by_supplier = {}
        if supplier_ids:
            sp = ','.join('?' * len(supplier_ids))
            sup_rows = conn.execute(
                f"SELECT id, name, email, phone, min_order_value FROM suppliers "
                f"WHERE company_id=? AND id IN ({sp})",
                [cid, *supplier_ids]
            ).fetchall()
            suppliers_by_id = {r['id']: dict(r) for r in sup_rows}

            contact_rows = conn.execute(
                f"SELECT * FROM supplier_contacts WHERE company_id=? AND supplier_id IN ({sp})",
                [cid, *supplier_ids]
            ).fetchall()
            for r in contact_rows:
                contacts_by_supplier.setdefault(r['supplier_id'], []).append(dict(r))
    finally:
        conn.close()

    result = po_split.group_basket_by_supplier(basket, suppliers=suppliers_by_id, contacts=contacts_by_supplier)
    return jsonify({'status': 'success', 'data': result})

# ── Stock Transfers (launch-readiness "inter-branch transfers", schema v28) ────
# ROADMAP.md's 2026-08-31 "retail v28 CLAIMED for inter-branch transfers" entry;
# database/schema.py's _migrate_add_stock_transfers docstring carries the full
# design reasoning (two-phase SEND/RECEIVE, why quantity_sent/quantity_received
# are separate columns rather than one quantity plus a flag, why the id is a
# client-style UUID rather than an autoincrement). This block is the half that
# docstring explicitly deferred: "wiring that write is retail_api.py's job, not
# schema's -- this migration only gives the movement itself somewhere to live."
#
# CAPABILITY: CAP_STOCK_ADJUST on every mutation below, never a new code --
# moving stock between two branches is a stock adjustment at BOTH ends, the
# exact authority adjust_stock/receive_purchase_order already require (the
# migration docstring's own words). The two read routes carry NONE, matching
# list_purchase_orders/get_purchase_order immediately above: a plain list/get
# discloses no pricing or margin, the same tier list_purchase_orders is already
# trusted with.
#
# OVERSELLING AT SEND: refused hard, no relaxation -- the SAME posture
# adjust_stock already takes, not create_sale's. create_sale's stage 7d-iii
# relaxation exists for a narrow, specific situation: a cashier stands in
# front of a paying customer whose stock is visibly on the shelf, and the
# ONLY reason the recorded balance might disagree is that THIS device is
# behind on a multi-device sync it does not control -- refusing a sale the
# cashier can see with their own eyes is worse than the oversell it might
# cause. Sending a transfer has neither ingredient: nobody is being turned
# away at a register, and a transfer sits in 'pending' -- inspectable,
# editable by re-creating, cancellable -- right up until the operator
# presses Send, so a wrong count is fixed by fixing the count before
# sending, not by shipping stock the source branch does not physically
# have. adjust_stock already answered this exact question for this exact
# kind of write (an operator-declared, single-device stock mutation with no
# "another device already moved it" story) and refuses outright; this route
# follows that precedent rather than inventing a second one.
#
# STOCK MOVEMENT PATH: SEND and RECEIVE write inventory_balances +
# inventory_movements the IDENTICAL way adjust_stock/receive_purchase_order
# already do -- same `INSERT OR IGNORE` balance seed, same
# `UPDATE ... quantity_on_hand = quantity_on_hand +/- ?`, same v13 actor
# stamp (_stamp()), same _queue_sync_event shape for the movement row. No
# second code path is invented for "the stock changed" -- see each route's
# own comment for the line-by-line correspondence to its precedent.
#
# `stock_transfers`/`stock_transfer_items` are members of neither
# RETAIL_UID_TABLES nor RETAIL_ACTOR_TABLES (database/schema.py) -- the
# header row's own `id` IS its wire identity (matching cash_sessions/
# reorder_requests), and it carries no v13 actor triple of its own (matching
# the migration docstring's reasoning for `created_by TEXT DEFAULT
# 'System'`, the SAME free-text column inventory_movements has always had).
# Only the `inventory_movements` rows this file writes at SEND/RECEIVE need
# the actor triple, because THAT table is a RETAIL_ACTOR_TABLES member.
# Neither table carries row_version/updated_at_utc/deleted_at_utc either
# (not a RETAIL_ROW_VERSION_TABLES member) -- there is no sync-delta
# machinery to feed for the header row itself, only for the movement rows,
# which already have their own (see _queue_sync_event calls below).

@retail_bp.route('/stock-transfers', methods=['GET'])
@mt_login_required
@mt_require_subsystem('retail')
def list_stock_transfers():
    """Company-scoped list, optionally filtered by `?branch_id=` (either end
    of the transfer -- "what has this branch sent" and "what is this branch
    expecting" are both real questions from one branch's point of view, so
    `branch_id` matches source OR destination rather than requiring the
    caller to know which) and/or `?status=`. No @mt_require_capability --
    matching list_purchase_orders above, a plain list of transfers discloses
    no pricing or margin, the same disclosure tier that route is already
    trusted with."""
    cid = _cid()
    branch_id = request.args.get('branch_id')
    status = request.args.get('status')
    conn = get_retail_conn()
    # Company condition on the JOIN, not the WHERE -- same cross-tenant-leak
    # discipline list_purchase_orders/get_purchase_order already established
    # above: this is a LEFT JOIN, and a branch id that somehow does not
    # resolve (never expected in practice; branches are never deleted) must
    # still return the transfer row with a blank name, not disappear from
    # the list entirely.
    query = """
        SELECT t.*, sb.name AS source_branch_name, db.name AS destination_branch_name
        FROM stock_transfers t
        LEFT JOIN branches sb ON sb.id=t.source_branch_id AND sb.company_id=t.company_id
        LEFT JOIN branches db ON db.id=t.destination_branch_id AND db.company_id=t.company_id
        WHERE t.company_id=?
    """
    params = [cid]
    if branch_id:
        query += " AND (t.source_branch_id=? OR t.destination_branch_id=?)"
        params.extend([branch_id, branch_id])
    if status:
        query += " AND t.status=?"
        params.append(status)
    query += " ORDER BY t.created_at DESC LIMIT 200"
    rows = conn.execute(query, params).fetchall()
    conn.close()
    return jsonify({'status': 'success', 'data': [dict(r) for r in rows]})


@retail_bp.route('/stock-transfers/<string:transfer_id>', methods=['GET'])
@mt_login_required
@mt_require_subsystem('retail')
def get_stock_transfer(transfer_id):
    """One transfer plus its lines -- same shape list_stock_transfers uses
    for the header, joined with product name/sku for each line (matching
    get_purchase_order's own items join immediately above in spirit)."""
    cid = _cid()
    conn = get_retail_conn()
    transfer = conn.execute("""
        SELECT t.*, sb.name AS source_branch_name, db.name AS destination_branch_name
        FROM stock_transfers t
        LEFT JOIN branches sb ON sb.id=t.source_branch_id AND sb.company_id=t.company_id
        LEFT JOIN branches db ON db.id=t.destination_branch_id AND db.company_id=t.company_id
        WHERE t.id=? AND t.company_id=?
    """, (transfer_id, cid)).fetchone()
    if not transfer:
        conn.close()
        return jsonify({'status': 'error', 'message': 'Transfer not found'}), 404
    items = conn.execute("""
        SELECT i.*, p.name AS product_name, p.sku
        FROM stock_transfer_items i LEFT JOIN products p ON p.id=i.product_id
        WHERE i.transfer_id=?
    """, (transfer_id,)).fetchall()
    conn.close()
    return jsonify({'status': 'success', 'data': {'transfer': dict(transfer), 'items': [dict(i) for i in items]}})


@retail_bp.route('/stock-transfers', methods=['POST'])
@mt_login_required
@mt_require_subsystem('retail')
@require_license_capability("retail.stock.transfer.create", restricted_mode_allowlist=RETAIL_RESTRICTED_ALLOWLIST)
@mt_require_capability(CAP_STOCK_ADJUST)
def create_stock_transfer():
    """CREATE only -- status='pending', no stock moves yet (see the section
    header above for why the two-phase design puts nothing on the ledger
    until SEND). Body: `{source_branch_id, destination_branch_id,
    items: [{product_id, quantity}, ...]}`.

    Both branches are validated to belong to THIS company -- the identical
    cross-tenant-leak shape create_purchase_order's own supplier_id/branch_id
    comments already document at length above -- and to differ from each
    other: a transfer to the branch you are standing in is a bug (nothing
    would ever leave or arrive anywhere), not a harmless no-op, so it is
    refused rather than silently accepted as a same-branch adjustment
    wearing a transfer's clothes.

    Product existence is checked the SAME way create_purchase_order checks
    its own basket immediately above (`status='active' AND deleted_at_utc IS
    NULL`) -- a brand-new transfer must not be raised against a product that
    no longer exists, for the identical reason a brand-new PO must not be.
    """
    data = request.json or {}
    cid  = _cid()
    items = data.get('items') or []
    if not items:
        return jsonify({'status': 'error', 'message': 'At least one item required'}), 400

    conn = get_retail_conn()
    try:
        try:
            source_bid = int(data.get('source_branch_id'))
            dest_bid = int(data.get('destination_branch_id'))
        except (TypeError, ValueError):
            return jsonify({'status': 'error',
                             'message': 'source_branch_id and destination_branch_id are required.'}), 400
        if source_bid == dest_bid:
            return jsonify({'status': 'error',
                             'message': 'Source and destination branch must be different.'}), 400

        valid_bids = {
            r['id'] for r in conn.execute(
                "SELECT id FROM branches WHERE company_id=? AND id IN (?,?)",
                (cid, source_bid, dest_bid)
            ).fetchall()
        }
        if source_bid not in valid_bids:
            return jsonify({'status': 'error', 'message': f'Unknown source_branch_id: {source_bid}'}), 400
        if dest_bid not in valid_bids:
            return jsonify({'status': 'error', 'message': f'Unknown destination_branch_id: {dest_bid}'}), 400

        parsed_items = []
        for item in items:
            pid = item.get('product_id')
            if not pid:
                return jsonify({'status': 'error', 'message': 'Every item requires a product_id'}), 400
            try:
                qty = float(item.get('quantity'))
            except (TypeError, ValueError):
                return jsonify({'status': 'error', 'message': f'Invalid quantity for product_id {pid}'}), 400
            if qty <= 0:
                return jsonify({'status': 'error',
                                 'message': f'Quantity must be greater than zero for product_id {pid}'}), 400
            parsed_items.append((pid, qty))

        product_ids = {pid for pid, _ in parsed_items}
        placeholders = ','.join('?' * len(product_ids))
        valid_products = {
            r['id'] for r in conn.execute(
                f"SELECT id FROM products WHERE company_id=? AND status='active' "
                f"AND deleted_at_utc IS NULL AND id IN ({placeholders})",
                [cid, *product_ids]
            ).fetchall()
        }
        missing_ids = product_ids - valid_products
        if missing_ids:
            return jsonify({'status': 'error', 'message': f'Unknown product_id: {sorted(missing_ids)[0]}'}), 400

        transfer_id = _new_uid()
        cur = conn.cursor()
        cur.execute(
            "INSERT INTO stock_transfers (id,company_id,source_branch_id,destination_branch_id,status,created_by) "
            "VALUES (?,?,?,?,'pending',?)",
            (transfer_id, cid, source_bid, dest_bid, _uid())
        )
        for pid, qty in parsed_items:
            cur.execute(
                "INSERT INTO stock_transfer_items (id,transfer_id,product_id,quantity_sent) VALUES (?,?,?,?)",
                (_new_uid(), transfer_id, pid, qty)
            )
        _audit(conn, 'STOCK_TRANSFER_CREATED', 'stock_transfer', transfer_id,
               f'{len(parsed_items)} line(s) from branch {source_bid} to {dest_bid}')
        conn.commit()
    except sqlite3.IntegrityError as exc:
        conn.rollback()
        current_app.logger.warning("create_stock_transfer failed on a database constraint: %s", exc)
        return jsonify({'status': 'error',
                         'message': 'This transfer could not be created because of a conflicting record.'}), 409
    except sqlite3.DatabaseError as exc:
        conn.rollback()
        current_app.logger.exception("create_stock_transfer failed: %s", exc)
        return jsonify({'status': 'error', 'message': 'Could not create this transfer.'}), 400
    finally:
        conn.close()
    return jsonify({'status': 'success', 'data': {'id': transfer_id}})


@retail_bp.route('/stock-transfers/<string:transfer_id>/send', methods=['POST'])
@mt_login_required
@mt_require_subsystem('retail')
@require_license_capability("retail.stock.transfer.send", restricted_mode_allowlist=RETAIL_RESTRICTED_ALLOWLIST)
@mt_require_capability(CAP_STOCK_ADJUST)
def send_stock_transfer(transfer_id):
    """pending -> in_transit. Stock LEAVES the source branch here -- the
    first of the two ledger-touching events this table exists to separate
    (see the section header above).

    BEGIN IMMEDIATE, same reasoning as receive_purchase_order's own
    docstring: two requests racing to send the SAME transfer (a
    double-clicked Send button) must not both walk the item loop and both
    decrement the source balance. The write lock is taken before the
    status is even read, and the closing UPDATE additionally carries
    `AND status='pending'` with its rowcount checked -- belt and braces,
    exactly like receive_purchase_order's own pair of guards.

    Each line is validated and written in ONE pass, sequentially, on the
    SAME connection -- not validated in a first pass and written in a
    second the way create_sale's multi-line demand accumulator has to be
    (create_sale's validation loop runs before its write loop, so it needs
    a running total to catch two lines of the same product summing past
    stock). Here validate-then-write happens per line, so a second line for
    a product a prior line in this SAME request already decremented reads
    the balance AFTER that decrement, on this same uncommitted transaction --
    the correct, already-reduced figure -- with no accumulator required.

    Refuses (400, nothing written) rather than allow the source balance to
    go negative -- see the section header's "OVERSELLING AT SEND" comment
    for why this follows adjust_stock's posture rather than create_sale's.
    """
    cid  = _cid()
    conn = get_retail_conn()
    try:
        conn.execute("BEGIN IMMEDIATE")
        cur = conn.cursor()
        transfer = cur.execute(
            "SELECT * FROM stock_transfers WHERE id=? AND company_id=?", (transfer_id, cid)
        ).fetchone()
        if not transfer:
            conn.rollback()
            return jsonify({'status': 'error', 'message': 'Transfer not found'}), 404
        if transfer['status'] != 'pending':
            conn.rollback()
            return jsonify({'status': 'error',
                             'message': f"Cannot send a transfer that is {transfer['status']}."}), 409

        items = cur.execute(
            "SELECT * FROM stock_transfer_items WHERE transfer_id=?", (transfer_id,)
        ).fetchall()

        source_bid = transfer['source_branch_id']
        reference = f'XFER-{transfer_id}'
        actor, terminal, utc_now = _stamp()
        source_branch_uid = _branch_uid(conn, source_bid)
        # Schema v40 (per-branch cost basis): drives the quantization of the
        # cost this loop snapshots below -- see `_money`'s own docstring,
        # same reasoning receive_purchase_order's identical line already
        # states.
        currency = _company_currency(conn, cid)
        sent_lines = []  # STOCK-BOOKS B4: (product_id, qty, unit_cost) for the send journal
        for item in items:
            pid = item['product_id']
            qty = float(item['quantity_sent'])
            # Same seed-then-read-then-update shape as adjust_stock above --
            # a branch that has never stocked this product yet gets a zero
            # row rather than a missing one, so the SELECT just below always
            # finds a row to read. `avg_cost` added to this SELECT (schema
            # v40): the source branch's OWN weighted average, read here so
            # the movement below can carry it -- removing stock at the
            # existing average does not change a weighted average, so this
            # read needs no recomputation, unlike receive_purchase_order's
            # or receive_stock_transfer's own weighted-average updates.
            cur.execute(
                "INSERT OR IGNORE INTO inventory_balances (company_id,product_id,branch_id,quantity_on_hand) "
                "VALUES (?,?,?,0)",
                (cid, pid, source_bid)
            )
            row = cur.execute(
                "SELECT quantity_on_hand, avg_cost FROM inventory_balances "
                "WHERE company_id=? AND product_id=? AND branch_id=?",
                (cid, pid, source_bid)
            ).fetchone()
            on_hand = float(row['quantity_on_hand'] or 0) if row else 0.0
            # Epsilon tolerance, not a bare `< 0` -- the SAME constant and
            # the SAME reasoning as adjust_stock's identical guard above:
            # quantity_on_hand is REAL and accumulated by repeated +/-
            # UPDATEs, so a fractional-unit product can legitimately sit at
            # 0.7999999999999999 rather than 0.8.
            if on_hand - qty < -stock_reconciliation.DEFAULT_TOLERANCE:
                conn.rollback()
                return jsonify({'status': 'error',
                                 'message': f'Cannot send {qty} of product {pid} -- '
                                            f'only {on_hand} on hand at the source branch.'}), 400
            # Schema v40: the SAME three-level fallback chain create_sale's
            # own cost snapshot now reads (branch avg_cost -> products.
            # avg_cost -> products.cost_price) -- a source branch that has
            # never received stock of its own (this row's `avg_cost` still
            # 0, the column default) falls through to the company-wide
            # figure rather than transferring stock at a false zero cost.
            # No negative-result guard needed here, unlike the weighted-
            # average WRITES elsewhere in this file: this is a plain READ of
            # an already-guarded figure, never a new computation that could
            # itself go negative.
            branch_avg_cost = float(row['avg_cost'] or 0) if row else 0.0
            product_cost_row = cur.execute(
                "SELECT avg_cost, cost_price FROM products WHERE id=? AND company_id=?",
                (pid, cid)
            ).fetchone()
            company_avg_cost = float(product_cost_row['avg_cost'] or 0) if product_cost_row else 0.0
            product_cost_price = float(product_cost_row['cost_price'] or 0) if product_cost_row else 0.0
            transfer_unit_cost = _money(
                branch_avg_cost if branch_avg_cost else (
                    company_avg_cost if company_avg_cost else product_cost_price),
                currency
            )
            cur.execute(
                "UPDATE inventory_balances SET quantity_on_hand = quantity_on_hand - ? "
                "WHERE company_id=? AND product_id=? AND branch_id=?",
                (qty, cid, pid, source_bid)
            )
            # Schema v40: persist the snapshot onto THIS line's own
            # stock_transfer_items row (keyed by item id, not product_id --
            # see database/schema.py's v40 migration docstring for why: a
            # transfer may carry two lines for the same product, and only
            # the item id disambiguates which line a given receive-time
            # count belongs to, the identical reason `quantity_received`
            # already keys by item id). `receive_stock_transfer` reads this
            # back to weight it into the destination branch's average.
            cur.execute(
                "UPDATE stock_transfer_items SET unit_cost=? WHERE id=?",
                (transfer_unit_cost, item['id'])
            )
            sent_lines.append((pid, qty, transfer_unit_cost))
            # v13 stamp + ledger row, identical shape to adjust_stock's own
            # INSERT above -- 'transfer_out' is a new, self-describing
            # movement_type; movement_type carries no CHECK constraint in
            # this schema (validated at the API layer only, same as every
            # other movement_type/status vocabulary in this file), and
            # `quantity` itself is signed (-qty), which is what
            # stock_reconciliation.compute_drift's SUM(quantity) actually
            # relies on -- the label is documentation, the sign is the math.
            # `unit_cost` now carries the real snapshot (schema v40) rather
            # than the column's own DEFAULT 0 -- stock moving between
            # branches now carries its cost with it, per ROADMAP.md's v40
            # entry, rather than the "harmless while cost was company-wide"
            # zero v39 deliberately left in place.
            movement_uid = _new_uid()
            cur.execute("""
                INSERT INTO inventory_movements (company_id,product_id,branch_id,movement_type,quantity,unit_cost,reference,notes,created_by,
                                                 uid,actor_user_uid,terminal_id,created_at_utc)
                VALUES (?,?,?,'transfer_out',?,?,?,?,?,?,?,?,?)
            """, (cid, pid, source_bid, -qty, transfer_unit_cost, reference,
                  f'Transfer to branch {transfer["destination_branch_id"]}', _uid(),
                  movement_uid, actor, terminal, utc_now))
            _queue_sync_event(cur, 'inventory_movement', movement_uid, 'create', {
                'uid': movement_uid, 'product_id': pid, 'branch_id': source_bid, 'branch_uid': source_branch_uid,
                'movement_type': 'transfer_out', 'quantity': -qty, 'unit_cost': transfer_unit_cost,
                'reference': reference, 'notes': f'Transfer to branch {transfer["destination_branch_id"]}',
                'created_by': _uid(), 'actor_user_uid': actor, 'terminal_id': terminal, 'created_at_utc': utc_now,
            })

        cur.execute(
            "UPDATE stock_transfers SET status='in_transit', sent_at=? "
            "WHERE id=? AND company_id=? AND status='pending'",
            (utc_now, transfer_id, cid)
        )
        if cur.rowcount != 1:
            # Another request won the race between our own SELECT above and
            # this UPDATE -- belt and braces, matching receive_purchase_
            # order's identical double-guard.
            conn.rollback()
            return jsonify({'status': 'error', 'message': 'Transfer already sent.'}), 409
        # STOCK-BOOKS B4: the stock is now in a van, not on a shelf -- Dr Stock
        # in Transit (1250) / Cr Inventory (1200) at the cost just snapshotted
        # on each line. Same transaction as the movements above.
        gl.post_transfer_send(conn, cid, source_bid, transfer_id, sent_lines, currency)
        _audit(conn, 'STOCK_TRANSFER_SENT', 'stock_transfer', transfer_id,
               f'{len(items)} line(s) from branch {source_bid} to {transfer["destination_branch_id"]}')
        conn.commit()
    except sqlite3.DatabaseError as exc:
        conn.rollback()
        current_app.logger.exception("send_stock_transfer(%s) failed: %s", transfer_id, exc)
        return jsonify({'status': 'error', 'message': 'Could not send this transfer.'}), 400
    finally:
        conn.close()
    return jsonify({'status': 'success'})


@retail_bp.route('/stock-transfers/<string:transfer_id>/receive', methods=['POST'])
@mt_login_required
@mt_require_subsystem('retail')
@require_license_capability("retail.stock.transfer.receive", restricted_mode_allowlist=RETAIL_RESTRICTED_ALLOWLIST)
@mt_require_capability(CAP_STOCK_ADJUST)
def receive_stock_transfer(transfer_id):
    """in_transit -> received. Stock ARRIVES at the destination branch here
    -- the second of the two ledger-touching events (see the section header
    above).

    Body: `{items: [{id, quantity_received}, ...]}` -- `id` is the
    stock_transfer_items row id (NOT product_id: a transfer may carry two
    lines for the same product, and only the item id disambiguates which
    line a given count belongs to). EVERY line of the transfer must be
    named exactly once, matching receive_purchase_order's own all-or-
    nothing receipt (no partial-PO-receiving exists in this file either) --
    a transfer half-reconciled would leave `status='in_transit'` forever
    with no way back to 'pending' and no way forward to 'received', so this
    route asks for every line's count in the one call that flips the status.

    A SHORTAGE (quantity_received < quantity_sent) is NOT an error -- see
    the migration docstring's STATUS VALUES section: 'received' is the same
    status regardless of whether every line matched exactly, because a
    discrepancy is a fact about the LINE, not a workflow state of the
    header. `quantity_received=0` is itself a real, meaningful value ("sent
    but none arrived") and writes NO inventory_movements row and moves NO
    stock, exactly as NULL vs 0 is documented to mean in the migration's own
    words. The response's `shortages` list surfaces every line that came up
    short, sourced from the SAME numbers just written, so the shop sees it
    immediately rather than having to notice on a stock report later.

    BEGIN IMMEDIATE + a conditional `status='in_transit'` UPDATE with its
    rowcount checked -- the identical double-guard send_stock_transfer's own
    docstring explains, now protecting against a double-clicked Receive
    instead of a double-clicked Send.
    """
    data = request.json or {}
    cid  = _cid()
    conn = get_retail_conn()
    try:
        conn.execute("BEGIN IMMEDIATE")
        cur = conn.cursor()
        transfer = cur.execute(
            "SELECT * FROM stock_transfers WHERE id=? AND company_id=?", (transfer_id, cid)
        ).fetchone()
        if not transfer:
            conn.rollback()
            return jsonify({'status': 'error', 'message': 'Transfer not found'}), 404
        if transfer['status'] != 'in_transit':
            conn.rollback()
            return jsonify({'status': 'error',
                             'message': f"Cannot receive a transfer that is {transfer['status']}."}), 409

        items = cur.execute(
            "SELECT * FROM stock_transfer_items WHERE transfer_id=?", (transfer_id,)
        ).fetchall()

        received_by_item_id = {}
        for entry in (data.get('items') or []):
            item_id = entry.get('id')
            if not item_id:
                conn.rollback()
                return jsonify({'status': 'error', 'message': 'Every received item requires its id.'}), 400
            try:
                qty_received = float(entry.get('quantity_received'))
            except (TypeError, ValueError):
                conn.rollback()
                return jsonify({'status': 'error',
                                 'message': f'Invalid quantity_received for item {item_id}.'}), 400
            if qty_received < 0:
                conn.rollback()
                return jsonify({'status': 'error',
                                 'message': f'quantity_received cannot be negative for item {item_id}.'}), 400
            received_by_item_id[item_id] = qty_received

        valid_item_ids = {item['id'] for item in items}
        unknown_ids = set(received_by_item_id) - valid_item_ids
        if unknown_ids:
            conn.rollback()
            return jsonify({'status': 'error',
                             'message': f'Unknown transfer item id: {sorted(unknown_ids)[0]}'}), 400
        unreconciled_ids = valid_item_ids - set(received_by_item_id)
        if unreconciled_ids:
            conn.rollback()
            return jsonify({'status': 'error',
                             'message': 'Every line of this transfer must be reconciled.'}), 400

        dest_bid = transfer['destination_branch_id']
        reference = f'XFER-{transfer_id}'
        actor, terminal, utc_now = _stamp()
        dest_branch_uid = _branch_uid(conn, dest_bid)
        # Schema v40 (per-branch cost basis): drives the quantization of the
        # destination branch's weighted-average update below -- same
        # `currency` every other moving-average write in this file is
        # quantized at.
        currency = _company_currency(conn, cid)
        shortages = []
        recv_lines = []  # STOCK-BOOKS B4: keyed by ITEM id (a transfer may repeat a product)
        for item in items:
            pid = item['product_id']
            qty_sent = float(item['quantity_sent'])
            qty_received = received_by_item_id[item['id']]
            recv_lines.append((item['id'], qty_sent, qty_received, float(item['unit_cost'] or 0)))
            cur.execute(
                "UPDATE stock_transfer_items SET quantity_received=? WHERE id=?",
                (qty_received, item['id'])
            )
            if qty_received > 0:
                # Schema v40: the cost THIS line left the source branch at,
                # snapshotted by send_stock_transfer onto this SAME row (see
                # that route's own comment) -- the figure being carried into
                # the destination branch's average below. 0 only for a
                # transfer sent before this column existed (never
                # backfilled -- see database/schema.py's v40 migration
                # docstring), in which case the weighted-average formula
                # below degrades to "incoming stock arrives at zero cost",
                # identical to every v39-and-earlier transfer's actual
                # behaviour, not a new defect this migration introduces.
                incoming_unit_cost = float(item['unit_cost'] or 0)
                # Same seed-then-update shape as receive_purchase_order's own
                # item loop above -- a destination branch that has never
                # stocked this product yet gets a zero row first. Read
                # BEFORE the UPDATE below moves `quantity_on_hand`, same
                # "weight the stock already on hand against the stock
                # arriving now" ordering receive_purchase_order's own
                # company-wide computation already follows.
                cur.execute(
                    "INSERT OR IGNORE INTO inventory_balances (company_id,product_id,branch_id,quantity_on_hand) "
                    "VALUES (?,?,?,0)",
                    (cid, pid, dest_bid)
                )
                dest_bal_row = cur.execute(
                    "SELECT quantity_on_hand, avg_cost FROM inventory_balances "
                    "WHERE company_id=? AND product_id=? AND branch_id=?",
                    (cid, pid, dest_bid)
                ).fetchone()
                dest_qty_on_hand = float(dest_bal_row['quantity_on_hand']) if dest_bal_row else 0.0
                dest_old_avg = float(dest_bal_row['avg_cost'] or 0) if dest_bal_row else 0.0
                dest_denom = dest_qty_on_hand + qty_received
                # Identical zero/negative-denominator and negative-numerator
                # guards as receive_purchase_order's own moving-average
                # write -- see that route's AUDIT comment (2026-09-21) for
                # the full reasoning this mirrors per branch. An EMPTY
                # destination branch (`dest_qty_on_hand == 0`, no balance row
                # or a zeroed one) collapses this formula to exactly
                # `incoming_unit_cost` -- "transferring into an empty branch
                # gives it exactly the sender's cost" falls out of the
                # weighted-average arithmetic with no special-casing needed,
                # the same way a first PO receipt does.
                # STOCK-BOOKS verify F1: shared rule (commercial_runtime/stock_cost.py).
                dest_new_avg_cost = _money(_blended_unit_cost(
                    dest_qty_on_hand, dest_old_avg, qty_received, incoming_unit_cost), currency)
                cur.execute(
                    "UPDATE inventory_balances SET quantity_on_hand = quantity_on_hand + ?, avg_cost = ? "
                    "WHERE company_id=? AND product_id=? AND branch_id=?",
                    (qty_received, dest_new_avg_cost, cid, pid, dest_bid)
                )
                # `unit_cost` now carries the real incoming snapshot (schema
                # v40) rather than the column's own DEFAULT 0 -- the SAME
                # figure just weighted into the destination average above,
                # so the immutable ledger row and the mutable cache it feeds
                # agree by construction.
                movement_uid = _new_uid()
                cur.execute("""
                    INSERT INTO inventory_movements (company_id,product_id,branch_id,movement_type,quantity,unit_cost,reference,notes,created_by,
                                                     uid,actor_user_uid,terminal_id,created_at_utc)
                    VALUES (?,?,?,'transfer_in',?,?,?,?,?,?,?,?,?)
                """, (cid, pid, dest_bid, qty_received, incoming_unit_cost, reference,
                      f'Transfer from branch {transfer["source_branch_id"]}', _uid(),
                      movement_uid, actor, terminal, utc_now))
                _queue_sync_event(cur, 'inventory_movement', movement_uid, 'create', {
                    'uid': movement_uid, 'product_id': pid, 'branch_id': dest_bid, 'branch_uid': dest_branch_uid,
                    'movement_type': 'transfer_in', 'quantity': qty_received, 'unit_cost': incoming_unit_cost,
                    'reference': reference, 'notes': f'Transfer from branch {transfer["source_branch_id"]}',
                    'created_by': _uid(), 'actor_user_uid': actor, 'terminal_id': terminal, 'created_at_utc': utc_now,
                })
            # qty_received == 0 writes no movement and moves no stock -- see
            # this route's own docstring: 0 is itself the real, meaningful
            # fact ("sent but none arrived"), not an absence to special-case.
            if qty_received < qty_sent - stock_reconciliation.DEFAULT_TOLERANCE:
                shortages.append({
                    'product_id': pid, 'quantity_sent': qty_sent, 'quantity_received': qty_received,
                })

        cur.execute(
            "UPDATE stock_transfers SET status='received', received_at=? "
            "WHERE id=? AND company_id=? AND status='in_transit'",
            (utc_now, transfer_id, cid)
        )
        if cur.rowcount != 1:
            conn.rollback()
            return jsonify({'status': 'error', 'message': 'Transfer already received.'}), 409
        # STOCK-BOOKS B4: Dr Inventory (received) / Cr Stock in Transit (exactly
        # what the send journal debited) / the difference to Shrinkage (5910).
        # A shortage used to vanish: the stock left the source and never arrived
        # and nothing recorded the loss. A transfer sent before this wave has no
        # send journal; the helper then posts nothing (1250 never goes negative).
        _journal_id, written_off = gl.post_transfer_receive(
            conn, cid, dest_bid, transfer_id, recv_lines, currency)
        for s, line in zip(shortages, [l for l in recv_lines
                                       if l[2] < l[1] - stock_reconciliation.DEFAULT_TOLERANCE]):
            s['written_off_value'] = float(written_off.get(line[0], 0))
        _audit(conn, 'STOCK_TRANSFER_RECEIVED', 'stock_transfer', transfer_id,
               f'{len(items)} line(s) at branch {dest_bid}'
               + (f'; {len(shortages)} short' if shortages else ''))
        conn.commit()
    except sqlite3.DatabaseError as exc:
        conn.rollback()
        current_app.logger.exception("receive_stock_transfer(%s) failed: %s", transfer_id, exc)
        return jsonify({'status': 'error', 'message': 'Could not receive this transfer.'}), 400
    finally:
        conn.close()
    return jsonify({'status': 'success', 'data': {'shortages': shortages}})


@retail_bp.route('/stock-transfers/<string:transfer_id>/cancel', methods=['POST'])
@mt_login_required
@mt_require_subsystem('retail')
@require_license_capability("retail.stock.transfer.cancel", restricted_mode_allowlist=RETAIL_RESTRICTED_ALLOWLIST)
@mt_require_capability(CAP_STOCK_ADJUST)
def cancel_stock_transfer(transfer_id):
    """pending -> cancelled. Only while pending -- see the migration
    docstring's STATUS VALUES section: a 'pending' transfer has touched no
    ledger row yet, so cancelling one is a pure status flip with nothing to
    unwind. A transfer already 'in_transit' or 'received' has moved real
    stock and cannot be cancelled through this route (there is no unwind
    path here -- reversing an in-flight or completed transfer is a new
    transfer in the other direction, the same way a shipped sale is reversed
    through /returns rather than by editing the sale).

    BEGIN IMMEDIATE + a conditional `status='pending'` UPDATE with its
    rowcount checked, the identical guard shape send/receive already use --
    this stops a Cancel racing a concurrent Send from both succeeding.
    """
    cid  = _cid()
    conn = get_retail_conn()
    try:
        conn.execute("BEGIN IMMEDIATE")
        cur = conn.cursor()
        transfer = cur.execute(
            "SELECT status FROM stock_transfers WHERE id=? AND company_id=?", (transfer_id, cid)
        ).fetchone()
        if not transfer:
            conn.rollback()
            return jsonify({'status': 'error', 'message': 'Transfer not found'}), 404
        if transfer['status'] != 'pending':
            conn.rollback()
            return jsonify({'status': 'error',
                             'message': f"Cannot cancel a transfer that is {transfer['status']}."}), 409

        cur.execute(
            "UPDATE stock_transfers SET status='cancelled' WHERE id=? AND company_id=? AND status='pending'",
            (transfer_id, cid)
        )
        if cur.rowcount != 1:
            conn.rollback()
            return jsonify({'status': 'error', 'message': 'Transfer already sent or received.'}), 409
        _audit(conn, 'STOCK_TRANSFER_CANCELLED', 'stock_transfer', transfer_id)
        conn.commit()
    except sqlite3.DatabaseError as exc:
        conn.rollback()
        current_app.logger.exception("cancel_stock_transfer(%s) failed: %s", transfer_id, exc)
        return jsonify({'status': 'error', 'message': 'Could not cancel this transfer.'}), 400
    finally:
        conn.close()
    return jsonify({'status': 'success'})


@retail_bp.route('/stock-transfers/<string:transfer_id>/recall', methods=['POST'])
@mt_login_required
@mt_require_subsystem('retail')
@require_license_capability("retail.stock.transfer.cancel", restricted_mode_allowlist=RETAIL_RESTRICTED_ALLOWLIST)
@mt_require_capability(CAP_STOCK_ADJUST)
def recall_stock_transfer(transfer_id):
    """STOCK-BOOKS B4: in_transit -> cancelled. Bring a sent transfer back to
    the source branch before the destination has received it.

    cancel_stock_transfer refuses once stock has left (a pending transfer has
    touched nothing; a sent one has moved stock and, now, a books entry), so a
    wrongly sent transfer used to be stuck in transit for ever. Recall puts
    every line back: one `transfer_in` movement per line at the cost the line
    left at, the source balance's average re-weighted exactly like a receipt,
    and the books reverse the SEND journal (1250 back to 1200). A transfer sent
    before this wave has no send journal and the books post nothing.
    Status-guarded under BEGIN IMMEDIATE, so a recall racing a receive can only
    win once.
    """
    cid = _cid()
    conn = get_retail_conn()
    try:
        conn.execute("BEGIN IMMEDIATE")
        cur = conn.cursor()
        transfer = cur.execute("SELECT * FROM stock_transfers WHERE id=? AND company_id=?",
                               (transfer_id, cid)).fetchone()
        if not transfer:
            conn.rollback()
            return jsonify({'status': 'error', 'message': 'Transfer not found'}), 404
        if transfer['status'] != 'in_transit':
            conn.rollback()
            return jsonify({'status': 'error',
                            'message': f"Cannot recall a transfer that is {transfer['status']}."}), 409
        items = cur.execute("SELECT * FROM stock_transfer_items WHERE transfer_id=?", (transfer_id,)).fetchall()
        source_bid = transfer['source_branch_id']
        reference = f'XFER-{transfer_id}'
        actor, terminal, utc_now = _stamp()
        source_branch_uid = _branch_uid(conn, source_bid)
        currency = _company_currency(conn, cid)
        for item in items:
            pid = item['product_id']
            qty = float(item['quantity_sent'])
            unit_cost = float(item['unit_cost'] or 0)
            cur.execute("INSERT OR IGNORE INTO inventory_balances (company_id,product_id,branch_id,quantity_on_hand) "
                        "VALUES (?,?,?,0)", (cid, pid, source_bid))
            bal = cur.execute("SELECT quantity_on_hand, avg_cost FROM inventory_balances "
                              "WHERE company_id=? AND product_id=? AND branch_id=?",
                              (cid, pid, source_bid)).fetchone()
            on_hand = float(bal['quantity_on_hand'] or 0)
            old_avg = float(bal['avg_cost'] or 0)
            # STOCK-BOOKS verify F1+F2: the shared rule; a line that left at
            # unit_cost <= 0 (a legacy transfer, cost unknown) carries NO cost
            # information, so the source average stays exactly as it was
            # rather than being blended toward 0.
            new_avg_cost = _money(_blended_unit_cost(on_hand, old_avg, qty, unit_cost), currency)
            cur.execute("UPDATE inventory_balances SET quantity_on_hand = quantity_on_hand + ?, avg_cost = ? "
                        "WHERE company_id=? AND product_id=? AND branch_id=?",
                        (qty, new_avg_cost, cid, pid, source_bid))
            movement_uid = _new_uid()
            note = 'Recalled'
            cur.execute("""
                INSERT INTO inventory_movements (company_id,product_id,branch_id,movement_type,quantity,unit_cost,reference,notes,created_by,
                                                 uid,actor_user_uid,terminal_id,created_at_utc)
                VALUES (?,?,?,'transfer_in',?,?,?,?,?,?,?,?,?)
            """, (cid, pid, source_bid, qty, unit_cost, reference, note, _uid(),
                  movement_uid, actor, terminal, utc_now))
            _queue_sync_event(cur, 'inventory_movement', movement_uid, 'create', {
                'uid': movement_uid, 'product_id': pid, 'branch_id': source_bid, 'branch_uid': source_branch_uid,
                'movement_type': 'transfer_in', 'quantity': qty, 'unit_cost': unit_cost,
                'reference': reference, 'notes': note, 'created_by': _uid(),
                'actor_user_uid': actor, 'terminal_id': terminal, 'created_at_utc': utc_now,
            })
        cur.execute("UPDATE stock_transfers SET status='cancelled' "
                    "WHERE id=? AND company_id=? AND status='in_transit'", (transfer_id, cid))
        if cur.rowcount != 1:
            conn.rollback()
            return jsonify({'status': 'error', 'message': 'Transfer already received or recalled.'}), 409
        send = gl.send_journal(conn, cid, transfer_id)
        if send:
            gl.reverse_journal(conn, cid, send['id'], memo=f'Transfer {transfer_id} recalled')
        _audit(conn, 'STOCK_TRANSFER_RECALLED', 'stock_transfer', transfer_id,
               f'{len(items)} line(s) back to branch {source_bid}')
        conn.commit()
    except sqlite3.DatabaseError as exc:
        conn.rollback()
        current_app.logger.exception("recall_stock_transfer(%s) failed: %s", transfer_id, exc)
        return jsonify({'status': 'error', 'message': 'Could not recall this transfer.'}), 400
    finally:
        conn.close()
    return jsonify({'status': 'success'})


# ── Reorder Requests (feat/reorder-automation-foundation) ───────────────────────
# Foundation only: schema + the post-sale trigger (core/retail/reorder_hook.py,
# called from create_sale below) + this accept/decline surface for the Admin
# Center page (app-shell.js/subsystem-retail.js). The WhatsApp send itself is
# explicitly deferred -- see database/schema.py's
# _migrate_add_reorder_automation_foundation docstring.

@retail_bp.route('/reorder-requests', methods=['GET'])
@mt_login_required
@mt_require_subsystem('retail')
def list_reorder_requests():
    """Company-scoped list of PENDING reorder requests, each carrying its
    product/branch context for the Admin Center page. Read-only, so --
    matching list_products/list_purchase_orders above -- this route carries
    no @require_license_capability guard and no is_admin_device check of
    its own; the admin-only gate is client-side (app-shell.js hides the nav
    entry unless GET /api/devices/me reports is_admin_device=true). An
    optional `?branch_id=` filters to one branch; omitted, every branch for
    this company is returned -- an admin reviewing requests across branches
    is the normal case this page exists for."""
    cid = _cid()
    conn = get_retail_conn()
    branch_id = request.args.get('branch_id')
    query = """
        SELECT r.*, p.name AS product_name, p.sku, p.reorder_level, p.supplier_id,
               b.name AS branch_name
        FROM reorder_requests r
        JOIN products p ON p.id = r.product_id
        LEFT JOIN branches b ON b.id = r.branch_id
        WHERE r.company_id=? AND r.status='pending'
    """
    params = [cid]
    if branch_id:
        query += " AND r.branch_id=?"
        params.append(branch_id)
    query += " ORDER BY r.created_at DESC"
    rows = conn.execute(query, params).fetchall()
    conn.close()
    return jsonify({'status': 'success', 'data': [dict(r) for r in rows]})


@retail_bp.route('/reorder-requests/<string:rid>/accept', methods=['POST'])
@mt_login_required
@mt_require_subsystem('retail')
@require_license_capability("retail.reorder.manage", restricted_mode_allowlist=RETAIL_RESTRICTED_ALLOWLIST)
@mt_require_capability(CAP_STOCK_ADJUST)
def accept_reorder_request(rid):
    """Accepts a pending reorder request: drafts a purchase_order and queues
    it for sync, exactly like POST /purchase-orders does.

    W4a (schema v45): this used to say the PO was "deliberately never queued"
    because `purchase_orders.id` is a per-computer INTEGER AUTOINCREMENT and
    Owner's relay 400-rejects the WHOLE push batch on the first non-UUID
    entity_id (see database/schema.py's _migrate_add_reorder_automation_
    foundation). That reason is gone: v45 gives the order (and each line) a
    real `uid`, and the wire identity is the uid, never the integer id. So a
    reorder-drafted PO now crosses computers like any other and a sibling can
    receive or cancel it. The same events as create_purchase_order are queued,
    through the same helper (`_po_stamp_and_queue_create`), so the two mint
    sites cannot drift.
    """
    cid = _cid()
    conn = get_retail_conn()
    _ensure_credit_schema(conn)
    try:
        cur = conn.cursor()
        req = conn.execute(
            "SELECT * FROM reorder_requests WHERE id=? AND company_id=?", (rid, cid)
        ).fetchone()
        if not req:
            return jsonify({'status': 'error', 'message': 'Reorder request not found'}), 404
        if req['status'] != 'pending':
            return jsonify({'status': 'error', 'message': 'This request was already resolved.'}), 409

        # launch-readiness Phase 6 stage 6b-iii-a: `AND deleted_at_utc IS
        # NULL` added -- this is the WRITE gate phase6b-deltas-and-tombstones.md
        # names for `list_reorder_requests`'s own INNER JOIN trap: that list
        # route deliberately stays unfiltered so a pending request for a
        # since-deleted product remains visible and declinable, and THIS is
        # where deletion is actually enforced -- a tombstoned product now
        # falls into the existing "Product no longer exists" 404 below,
        # exactly like a hard-deleted id already did, so the request can be
        # declined but never accepted.
        #
        # `status='active'` joins the tombstone check for the same
        # two-population reason `create_supplier_contact`'s comment (this
        # file) spells out in full -- a product deleted before tombstones
        # existed never got a `deleted_at_utc` stamp, so it would otherwise
        # slip past this gate and get accepted onto a new PO.
        product = conn.execute(
            "SELECT id, name, supplier_id, cost_price, reorder_level FROM products "
            "WHERE id=? AND company_id=? AND status='active' AND deleted_at_utc IS NULL",
            (req['product_id'], cid),
        ).fetchone()
        if not product:
            return jsonify({'status': 'error', 'message': 'Product no longer exists.'}), 404

        # Phase-1 foundation heuristic (see core/retail/reorder_hook.py's
        # module docstring): restock exactly back up to reorder_level, never
        # a demand-based forecast -- refining this is explicitly out of
        # scope for this foundation wave. Uses products.supplier_id (schema
        # v5) -- deliberately NOT a new default_supplier_id column, which
        # would just duplicate that existing, already-synced FK.
        qty = max(float(product['reorder_level'] or 0), 1)
        unit_cost = float(product['cost_price'] or 0)
        # Same currency-aware quantization as create_purchase_order's own
        # `total` -- this route writes the identical purchase_orders.total
        # column through a second, independent mint site (see this route's
        # po_number comment below), and pay_purchase_order later reads that
        # stored total back through _money(po['total'], currency) to decide
        # payment_status. Leaving THIS write on the old 2dp default would
        # permanently truncate a JOD reorder-drafted PO's total at creation
        # time -- no later read could recover the fils, because they were
        # never stored.
        total = _money(unit_cost * qty, _company_currency(conn, cid))
        supplier_id = product['supplier_id']
        # STOCK-BOOKS verify F3: a reorder PO is born unpaid, so it is a credit
        # order -- it must name whom it is owed to (see create_purchase_order's
        # matching refusal for why). Nothing is written yet at this point.
        if not supplier_id and total > _money_epsilon(_company_currency(conn, cid)):
            return jsonify({'status': 'error', 'code': 'SUPPLIER_REQUIRED_FOR_CREDIT_PO',
                            'message': 'Set a supplier for this product first.'}), 409
        # `req['branch_id']` is a trusted value from THIS company's own
        # reorder_requests row -- the fallback below only applies to a
        # legacy row with no branch_id at all. Launch-readiness chain wave
        # C1: pin-aware, same reasoning as every other _default_branch call
        # site in this file.
        branch_id = req['branch_id'] or _resolve_working_branch(conn, cid)[0]

        # Identical AUDIT-032B treatment as create_purchase_order above (see
        # that route's comment for the full company-vs-company,
        # device-vs-device collision argument, and
        # _device_doc_discriminator's docstring for the wedge-sync failure
        # chain it closes) -- this route drafts a purchase_orders row from
        # the SAME _next_ref(conn, cid, 'po') call, so it carries the
        # identical bare-UNIQUE collision risk on po_number and needs the
        # identical fix. Fixing only the obvious mint site above and
        # missing this one would leave the bug fully live through the
        # reorder-accept path (2026-08-28 ROADMAP entry).
        #
        # Aseel-parity wave A-PAR (schema v34): identical treatment as
        # create_purchase_order's own 'po' mint site above -- see that
        # route's comment for the full reasoning. Both sites must resolve
        # a configured series or neither may, which is exactly what
        # retail_po_number_uniqueness_test.py's own two-mint-site coverage
        # is extended to prove for this feature.
        _po_series = _resolve_series_gated(conn, cid, 'po')
        if _po_series is not None:
            po_number = doc_series.allocate(conn, _po_series)
        else:
            po_number = _mint_legacy_doc_number(conn, cid, 'po')
        po_uid = _new_uid()   # W4a: wire identity from birth (see this route's docstring)
        cur.execute("""
            INSERT INTO purchase_orders (company_id,po_number,supplier_id,branch_id,status,subtotal,total,notes,
                                         ordered_at,amount_paid,payment_status,uid,ap_basis)
            VALUES (?,?,?,?,?,?,?,?,?,0,'unpaid',?,'receipt')
        """, (cid, po_number, supplier_id, branch_id, 'pending', total, total,
              f'{_REORDER_PO_NOTE_PREFIX}{rid}',
              datetime.now().strftime('%Y-%m-%d'), po_uid))
        po_id = cur.lastrowid
        cur.execute("""
            INSERT INTO purchase_order_items (po_id,product_id,quantity,unit_cost,total,uid)
            VALUES (?,?,?,?,?,?)
        """, (po_id, product['id'], qty, unit_cost, total, _new_uid()))
        # Queued below, once the order journal exists and its uid can ride along
        # (`_po_stamp_and_queue_create`) -- same transaction as these rows.

        # v44 F1 (verifier finding): this PO is a purchase_orders row, and
        # v44's supplier formula counts EVERY purchase_orders.total > eps as
        # owed. create_purchase_order books that same debt in the general
        # ledger (Dr Inventory / Cr AP) in the same transaction; this second
        # mint site posted NOTHING, so the supplier subledger said "owed
        # <total>" while the books said 0 and the AP tie went false. Fix at
        # the root: call the SAME posting create_purchase_order calls, with
        # the same gate (`ap_balance` only when a supplier exists and the
        # total is above the money epsilon; a reorder PO is born with no
        # down-payment so amount_paid is 0), inside this transaction, then
        # re-derive the supplier's display cache like every other writer.
        #
        # W4a-2: the order journal is gone for BOTH mint sites together (see
        # create_purchase_order): this PO is ap_basis='receipt', so it books
        # nothing until goods arrive, and the supplier's formula counts nothing
        # for it until then either -- the two cannot disagree. Nothing to post
        # here at all (a reorder PO is born with no down payment).
        _po_currency = _company_currency(conn, cid)
        if supplier_id:
            _refresh_party_balance(conn, 'suppliers', supplier_id, cid, _po_currency)
        _po_stamp_and_queue_create(cur, po_id, None)

        now = datetime.now(timezone.utc).isoformat()
        # launch-readiness Phase 6 stage 6a-i: `status`/`resolved_at` are
        # both synced reorder_request fields (sync_service.py's apply
        # branch), so this bumps row_version in the SAME UPDATE, reusing
        # the SAME `now` already computed for `resolved_at` as
        # `updated_at_utc` too -- one instant, not two.
        cur.execute(
            "UPDATE reorder_requests SET status='accepted', resolved_at=?, "
            "row_version=row_version+1, updated_at_utc=? WHERE id=?",
            (now, now, rid),
        )
        row = conn.execute("SELECT row_version FROM reorder_requests WHERE id=?", (rid,)).fetchone()
        # launch-readiness Phase 6 stage 6b-i (changed-field deltas): this
        # route changes exactly `status`/`resolved_at` -- see the SET clause
        # two statements above -- so `_changed_fields` names exactly those
        # two, letting the apply side leave `draft_message` (carried here
        # only because the INSERT half needs a full snapshot) untouched if
        # some other device edited it in the meantime.
        _queue_sync_event(cur, 'reorder_request', rid, 'update', {
            'id': rid, 'branch_id': req['branch_id'], 'product_id': req['product_id'],
            'status': 'accepted', 'draft_message': req['draft_message'], 'resolved_at': now,
            'row_version': row['row_version'], 'updated_at_utc': now,
            '_changed_fields': ['status', 'resolved_at'],
        })
        _audit(conn, 'REORDER_REQUEST_ACCEPTED', 'reorder_request', rid,
               f'PO {po_number} drafted for product {product["name"]}')
        _audit(conn, 'PO_CREATED', 'purchase_order', po_id, po_number)
        conn.commit()
        _sync_nudge()
        return jsonify({'status': 'success', 'data': {'purchase_order_id': po_id, 'po_number': po_number}})
    except Exception as e:
        conn.rollback()
        return jsonify({'status': 'error', 'message': str(e)}), 500
    finally:
        conn.close()


@retail_bp.route('/reorder-requests/<string:rid>/decline', methods=['POST'])
@mt_login_required
@mt_require_subsystem('retail')
@require_license_capability("retail.reorder.manage", restricted_mode_allowlist=RETAIL_RESTRICTED_ALLOWLIST)
@mt_require_capability(CAP_STOCK_ADJUST)
def decline_reorder_request(rid):
    """Declines a pending reorder request -- marks it declined and queues
    the sync event. Creates nothing else; unlike accept, there is no
    purchase_order to queue here (W4a: accept now queues its PO)."""
    cid = _cid()
    conn = get_retail_conn()
    try:
        cur = conn.cursor()
        req = conn.execute(
            "SELECT * FROM reorder_requests WHERE id=? AND company_id=?", (rid, cid)
        ).fetchone()
        if not req:
            return jsonify({'status': 'error', 'message': 'Reorder request not found'}), 404
        if req['status'] != 'pending':
            return jsonify({'status': 'error', 'message': 'This request was already resolved.'}), 409

        now = datetime.now(timezone.utc).isoformat()
        # launch-readiness Phase 6 stage 6a-i: same reasoning as
        # accept_reorder_request's identical comment above.
        cur.execute(
            "UPDATE reorder_requests SET status='declined', resolved_at=?, "
            "row_version=row_version+1, updated_at_utc=? WHERE id=?",
            (now, now, rid),
        )
        row = conn.execute("SELECT row_version FROM reorder_requests WHERE id=?", (rid,)).fetchone()
        # launch-readiness Phase 6 stage 6b-i: same reasoning as
        # accept_reorder_request's identical comment above.
        _queue_sync_event(cur, 'reorder_request', rid, 'update', {
            'id': rid, 'branch_id': req['branch_id'], 'product_id': req['product_id'],
            'status': 'declined', 'draft_message': req['draft_message'], 'resolved_at': now,
            'row_version': row['row_version'], 'updated_at_utc': now,
            '_changed_fields': ['status', 'resolved_at'],
        })
        _audit(conn, 'REORDER_REQUEST_DECLINED', 'reorder_request', rid)
        conn.commit()
        _sync_nudge()
        return jsonify({'status': 'success'})
    except Exception as e:
        conn.rollback()
        return jsonify({'status': 'error', 'message': str(e)}), 500
    finally:
        conn.close()

# ══════════════════════════════════════════════════════════════════════════════
#  Quotations and Sales Orders (Aseel-parity wave A-PAR, schema v33)
#
#  THIS IS NOT `held_sales` WEARING A NEW NAME. `held_sales` (below, this
#  file) is a device-local JSON cart snapshot with no approval step, no
#  expiry and no conversion tracking -- "two devices don't need to see each
#  other's in-progress carts" is true of a cart and false of a document a
#  customer is holding a printed copy of. A quotation/sales-order is its own
#  pair of real tables (database/schema.py's `_migrate_add_sales_quotations`
#  -- read that docstring first), not a bigger held_sales.
#
#  STAGE A ONLY (this wave). Every route below reads/writes
#  `sales_quotations`/`sales_quotation_lines` on THIS device and queues the
#  matching sync_outbox events (see DRAFTS DO NOT SYNC below) -- and, as of
#  this same change, `commercial_runtime/sync/sync_service.py`'s apply side
#  now has the matching `quotation` branch, so a quotation issued on one
#  device DOES converge to another once both have pulled. What it cannot do
#  is retroactively fetch an event emitted before a peer's cursor learned
#  the `quotation` entity type exists: `_apply_event` skips an unhandled
#  type and the cursor still advances past it (sync_service.py's own
#  module docstring), so a quotation sent before every device in a shop is
#  running this build never backfills to the ones that were not. Named here
#  rather than left for a two-till shop to discover.
#
#  DRAFTS DO NOT SYNC. No sync event is ever queued while `status='draft'`
#  -- the `held_sales` argument restated: a draft is device-local,
#  cart-shaped state nobody else needs to see. The FIRST event a quotation
#  ever produces is queued at SEND, as `event_type='create'`, carrying the
#  header AND the now-frozen line set in one payload (`payload['lines']`)
#  -- `sent` is IMMUTABLE (database/schema.py's STATUS VALUES), so lines can
#  never change again, and every LATER event (accept/decline/cancel/
#  convert) is `event_type='update'` carrying header fields only. This is
#  why update_quotation never queues a sync event at all (PUT is draft-only,
#  and a draft never syncs) and why cancel_quotation only queues one when
#  the quotation being cancelled was NOT still a draft.
#
#  NO NINTH CAPABILITY CODE. Every route below rides the existing CAP_SELL
#  -- "park/recall a cart" is already inside that code's own definition
#  (see the CAPABILITY GATING header far above), and a code with no seeded
#  row is a code nobody holds. ONE new LICENCE capability string,
#  `retail.quotation.manage`, matching `retail.promotion.manage`/
#  `retail.modifier.manage`/`retail.reorder.manage` already in that separate
#  vocabulary -- see docs/licensing/phase7/retail-restriction-capability-
#  matrix.md. NOT added to RETAIL_RESTRICTED_ALLOWLIST: a lapsed licence
#  must not issue new commercial promises.
#
#  A QUOTE RESERVES NO STOCK. `quotations_committed_demand` below is
#  ADVISORY ONLY, derived on read from accepted/unconverted/unexpired
#  quotations -- it never refuses a sale or a conversion. Four independent
#  reasons this is deliberate, not an oversight: (1) `inventory_balances.
#  quantity_reserved` already existed and was DROPPED in v17 as dead code;
#  reinstating it would argue against that migration, not design around it.
#  (2) Balances are DERIVED from `inventory_movements` (Phase 3's ledger-is-
#  truth); a reservation has no ledger row, so it either widens the drift
#  invariant v15 gates the whole migration chain on, or sits outside the one
#  number this codebase treats as truth. (3) Reservations do not CONVERGE:
#  two tills, five on hand, two quotes for five each, both locally legal --
#  no merge rule is right, the identical reason `customers.credit_balance`
#  is kept device-local. (4) It would let a document refuse a sale, which
#  create_sale's own stage 7d-iii comment already adjudicated against.
# ══════════════════════════════════════════════════════════════════════════════

#: `sales_quotations.status` values. No CHECK constraint (matching
#: `movement_type`/`stock_transfers.status`'s own precedent in this file) --
#: validated here, at the API layer.
_QUOTATION_STATUSES = ('draft', 'sent', 'accepted', 'declined', 'cancelled', 'converted')
_QUOTATION_DOC_KINDS = ('quotation', 'order')
#: Mirrors create_sale's own line-count reasoning for `_MAX_PUSH_BATCH` --
#: a SENT quotation carries its own frozen lines in ONE sync event, and the
#: relay batches at most 200 events per push.
_QUOTATION_MAX_LINES = 200


def _wants_discount(items):
    """Same predicate create_sale's own `wants_discount` uses (above,
    `create_sale`'s definition further down this file): any line whose
    CLAMPED discount_pct is > 0 asks for a discount. Deliberately PURE --
    no capability call inside it -- so create_quotation/update_quotation
    each keep their OWN inline `if ... and not session_has_capability(
    CAP_DISCOUNT): return ...`, which is what the AST capability ratchet
    (retail_capability_ratchet_ast.py) requires: the verdict must be
    consumed inside the SAME handler function, not merely computed by a
    shared helper two calls away."""
    return any(
        tax_engine.clamp_discount_pct(item.get('discount_pct', 0)) > 0
        for item in items if isinstance(item, dict)
    )


def _quotation_is_expired(valid_until, today_local):
    """`valid_until < today_local` -- a quote expiring TODAY is still valid
    for the rest of that day (database/schema.py's "EXPIRY IS DERIVED, NOT
    STORED" section). A NULL/empty `valid_until` never expires. Computed on
    every read and re-evaluated on every conversion attempt -- there is no
    stored 'expired' status to go stale."""
    return bool(valid_until) and valid_until < today_local


def _resolve_quotation_lines_for_write(conn, cid, bid, items, mode, currency):
    """Shared by create_quotation/update_quotation: resolves server-
    authoritative line data from client-submitted commercial intent, the
    IDENTICAL AUDIT-002/003 sequence create_sale's own item loop uses --
    promo_engine.load_active_promotions -> resolve_line_discount_pct ->
    tax_engine.calculate_line -- so a quote issued inside a promotion window
    is a real offer at the promoted price. Returns `(resolved_lines,
    subtotal, discount, tax, total, error_response)`; `error_response` is
    None on success and callers return it directly.

    NO STOCK CHECK HERE, deliberately: a quotation is a future promise, not
    a cart about to take money. The live stock check happens exactly once,
    at CONVERSION, inside create_sale (design point (e): "NO SPECIAL CASE,
    NONE") -- duplicating it here would be a SECOND oversell rule, the
    thing the stock_transfers section banner (above) already argues
    against.

    Parent-product guard copied verbatim from create_sale's own item loop
    (further down this file): a product with variants has no
    `inventory_balances` row of its own that means anything, so it is
    refused here exactly as it would be at the till.
    """
    if not items:
        return None, 0, 0, 0, 0, (jsonify({'status': 'error', 'message': 'At least one item required'}), 400)
    if len(items) > _QUOTATION_MAX_LINES:
        return None, 0, 0, 0, 0, (jsonify({
            'status': 'error',
            'message': f'A quotation may carry at most {_QUOTATION_MAX_LINES} lines.',
        }), 400)

    now_local = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
    active_promotions = promo_engine.load_active_promotions(conn, cid, bid, now_local)

    resolved_lines = []
    subtotal = discount = tax = total = Decimal('0')
    for line_no, item in enumerate(items, start=1):
        if not isinstance(item, dict):
            return None, 0, 0, 0, 0, (jsonify({'status': 'error', 'message': 'Invalid item.'}), 400)
        pid = item.get('product_id')
        product = conn.execute(
            "SELECT p.id, p.name, p.sell_price, p.tax_rate, p.status, p.category_id, "
            "p.parent_product_id, EXISTS("
            "  SELECT 1 FROM products c WHERE c.parent_product_id = p.id "
            "  AND c.company_id = p.company_id AND c.deleted_at_utc IS NULL "
            "  AND c.status='active'"
            ") AS has_variants "
            "FROM products p WHERE p.id=? AND p.company_id=? AND p.deleted_at_utc IS NULL",
            (pid, cid)
        ).fetchone()
        if not product:
            return None, 0, 0, 0, 0, (jsonify({'status': 'error', 'message': f'Product {pid} not found.'}), 400)
        if product['status'] != 'active':
            return None, 0, 0, 0, 0, (jsonify({
                'status': 'error', 'message': f'Product "{product["name"]}" is not available for sale.'}), 400)
        if product['has_variants']:
            return None, 0, 0, 0, 0, (jsonify({
                'status': 'error',
                'message': f'"{product["name"]}" has variants -- choose a specific variant to sell.'}), 400)
        try:
            qty = float(item.get('quantity'))
        except (TypeError, ValueError):
            return None, 0, 0, 0, 0, (jsonify({'status': 'error', 'message': 'Invalid quantity.'}), 400)
        if qty <= 0:
            return None, 0, 0, 0, 0, (jsonify({'status': 'error', 'message': 'Quantity must be greater than zero.'}), 400)

        manual_discount_pct = tax_engine.clamp_discount_pct(item.get('discount_pct', 0))
        effective_discount_pct, applied_promotion = promo_engine.resolve_line_discount_pct(
            active_promotions, pid, product['parent_product_id'], product['category_id'], manual_discount_pct
        )
        unit_price = float(product['sell_price'])
        tax_rate = float(product['tax_rate'])
        calc = tax_engine.calculate_line(unit_price, qty, effective_discount_pct, tax_rate, mode=mode, currency=currency)

        resolved_lines.append({
            'product_id': pid, 'product_name_snapshot': product['name'], 'quantity': qty,
            'unit_price': unit_price, 'discount_pct': effective_discount_pct, 'tax_rate': tax_rate,
            'line_total': calc['taxable_amount'],
            'promotion_name_snapshot': applied_promotion['name'] if applied_promotion else None,
            'line_no': line_no,
        })
        subtotal += Decimal(str(calc['gross']))
        discount += Decimal(str(calc['discount_amount']))
        tax += Decimal(str(calc['tax']))
        total += Decimal(str(calc['total']))

    quant = tax_engine.currency_quantum(currency)
    subtotal = float(subtotal.quantize(quant, rounding=ROUND_HALF_UP))
    discount = float(discount.quantize(quant, rounding=ROUND_HALF_UP))
    tax = float(tax.quantize(quant, rounding=ROUND_HALF_UP))
    total = float(total.quantize(quant, rounding=ROUND_HALF_UP))
    return resolved_lines, subtotal, discount, tax, total, None


def _quotation_sync_header_payload(conn, q, changed_fields=None):
    """The FULL header snapshot every quotation sync event carries -- see
    database/schema.py's "DRAFTS DO NOT SYNC" section. `q` is the ALREADY-
    UPDATED row (callers re-SELECT after their own UPDATE commits its
    values, rather than this function guessing what changed), so every
    caller gets a byte-correct snapshot with no risk of drifting from the
    write that just happened. `branch_uid` is resolved fresh every call --
    AUDIT-032C, the identical fix `sale`'s own emission uses -- NEVER the
    raw `branch_id` integer, which means nothing on a receiving device.
    `changed_fields`, when given, is the delta contract (stage 6b-i) the
    sync apply side's `_delta_set_clause` reads; omitted entirely for a
    `create` event, which the apply side then reads as "every column
    changed" -- correct, since a `create` event is this row's very first
    appearance on the wire.
    """
    payload = {
        'id': q['id'], 'branch_id': q['branch_id'], 'branch_uid': _branch_uid(conn, q['branch_id']),
        'customer_id': q['customer_id'], 'doc_number': q['doc_number'], 'doc_kind': q['doc_kind'],
        'status': q['status'], 'valid_until': q['valid_until'], 'currency': q['currency'],
        'tax_mode': q['tax_mode'], 'subtotal': q['subtotal'], 'discount_amount': q['discount_amount'],
        'tax_amount': q['tax_amount'], 'total': q['total'], 'notes': q['notes'],
        'created_at': str(q['created_at']) if q['created_at'] is not None else None,
        'created_by': q['created_by'],
        'sent_at': q['sent_at'], 'accepted_at': q['accepted_at'], 'declined_at': q['declined_at'],
        'cancelled_at': q['cancelled_at'], 'converted_at': q['converted_at'],
        'converted_sale_uid': q['converted_sale_uid'],
        'conversion_variance_json': q['conversion_variance_json'],
        'row_version': q['row_version'], 'updated_at_utc': q['updated_at_utc'],
    }
    if changed_fields is not None:
        payload['_changed_fields'] = changed_fields
    return payload


@retail_bp.route('/quotations', methods=['POST'])
@mt_login_required
@mt_require_subsystem('retail')
@require_license_capability("retail.quotation.manage", restricted_mode_allowlist=RETAIL_RESTRICTED_ALLOWLIST)
@mt_require_capability(CAP_SELL)
def create_quotation():
    """Body: `{branch_id?, customer_id?, doc_kind?, valid_until?, notes?,
    items:[{product_id, quantity, discount_pct?}]}`. Creates `status='draft'`
    -- see the section banner above for why a draft never syncs.

    AUDIT-002/003 UNCHANGED: the client sends commercial intent only.
    `unit_price`/`tax_rate`/`line_total` and all four header totals are
    resolved server-side (see `_resolve_quotation_lines_for_write`).

    INLINE CAP_DISCOUNT, judged AFTER `tax_engine.clamp_discount_pct` and
    BEFORE any write -- create_sale's exact shape. THIS gate matters MORE
    here than at the till: a quotation is a forward-dated discount. Without
    it a cashier who cannot type 20% off today could put 20% off in writing
    today and oblige the shop tomorrow.
    """
    data = request.json or {}
    cid = _cid()
    items = data.get('items') or []

    if _wants_discount(items) and not session_has_capability(CAP_DISCOUNT):
        return jsonify({'status': 'error', 'message': DISCOUNT_DENIED_MESSAGE}), 403

    doc_kind = data.get('doc_kind') or 'quotation'
    if doc_kind not in _QUOTATION_DOC_KINDS:
        return jsonify({'status': 'error', 'message': f'Invalid doc_kind: {doc_kind!r}'}), 400

    conn = get_retail_conn()
    # `_settings()` (below) and `_next_ref()` both read tables
    # (`retail_settings`, `doc_sequences`) that only exist once this LAZY,
    # route-triggered migration has run at least once on this database --
    # create_sale's own top-of-function call does the identical thing for
    # the identical reason (see sync_service.py's `apply_pull_result` "why
    # this hook exists" comment for the general shape of this trap: a brand
    # new device/company that has never hit a route which happens to call
    # this can otherwise 500 the FIRST time anything here reads either
    # table). Reproduced directly: a fresh company's first POST /quotations
    # raised `sqlite3.OperationalError: no such table: retail_settings`
    # before this call was added.
    _ensure_credit_schema(conn)
    try:
        # Launch-readiness chain wave C1's own fix (create_sale/create_
        # purchase_order/create_stock_transfer all resolve their branch
        # through this SAME convergence point -- see its own docstring).
        bid, branch_err = _resolve_working_branch(conn, cid, data.get('branch_id'))
        if branch_err:
            return branch_err

        _s = _settings(conn, cid)
        mode = _s.get('tax_calculation_mode', tax_engine.DEFAULT_MODE)
        currency = _s.get('base_currency')

        resolved_lines, subtotal, discount, tax, total, line_err = _resolve_quotation_lines_for_write(
            conn, cid, bid, items, mode, currency)
        if line_err:
            return line_err

        qid = _new_uid()
        # AUDIT-032B, both mitigations mandatory from commit one -- create_
        # purchase_order/create_sale's identical expression, minted BEFORE
        # the INSERT and wrapped in the same IntegrityError containment
        # below.
        doc_number = f"{_next_ref(conn, cid, 'quotation')}-{str(cid)[:8]}-{_device_doc_discriminator()}"
        now_utc = now_utc_iso()
        cur = conn.cursor()
        cur.execute("""
            INSERT INTO sales_quotations
                (id, company_id, branch_id, customer_id, doc_number, doc_kind, status,
                 valid_until, currency, tax_mode, subtotal, discount_amount, tax_amount, total,
                 notes, created_by, row_version, updated_at_utc)
            VALUES (?,?,?,?,?,?,'draft',?,?,?,?,?,?,?,?,?,1,?)
        """, (qid, cid, bid, data.get('customer_id'), doc_number, doc_kind,
              data.get('valid_until'), currency, mode, subtotal, discount, tax, total,
              data.get('notes', ''), data.get('cashier', _uid()), now_utc))

        for line in resolved_lines:
            cur.execute("""
                INSERT INTO sales_quotation_lines
                    (id, quotation_id, product_id, product_name_snapshot, quantity,
                     unit_price, discount_pct, tax_rate, line_total, promotion_name_snapshot, line_no)
                VALUES (?,?,?,?,?,?,?,?,?,?,?)
            """, (_new_uid(), qid, line['product_id'], line['product_name_snapshot'], line['quantity'],
                  line['unit_price'], line['discount_pct'], line['tax_rate'], line['line_total'],
                  line['promotion_name_snapshot'], line['line_no']))
        # DRAFTS DO NOT SYNC (section banner above) -- no _queue_sync_event
        # call here. The first sync event this quotation ever produces is
        # queued by send_quotation, below.
        _audit(conn, 'QUOTATION_CREATED', 'quotation', qid, doc_number)
        conn.commit()
    except sqlite3.IntegrityError as exc:
        conn.rollback()
        current_app.logger.warning("create_quotation failed on a database constraint: %s", exc)
        return jsonify({
            'status': 'error',
            'message': 'This quotation could not be created because of a conflicting record. Please try again.',
        }), 409
    except sqlite3.DatabaseError as exc:
        conn.rollback()
        current_app.logger.exception("create_quotation failed: %s", exc)
        return jsonify({'status': 'error', 'message': 'Could not create this quotation.'}), 400
    finally:
        conn.close()
    return jsonify({'status': 'success', 'data': {'id': qid, 'doc_number': doc_number}}), 201


@retail_bp.route('/quotations/<string:qid>', methods=['PUT'])
@mt_login_required
@mt_require_subsystem('retail')
@require_license_capability("retail.quotation.manage", restricted_mode_allowlist=RETAIL_RESTRICTED_ALLOWLIST)
@mt_require_capability(CAP_SELL)
def update_quotation(qid):
    """DRAFT ONLY -- enforced by a conditional UPDATE whose `cur.rowcount`
    is checked, 409 otherwise (receive_purchase_order/cancel_stock_
    transfer's own guard shape). `doc_kind` and `branch_id` are IMMUTABLE
    through this route: `doc_kind` by design (records how the document
    STARTED -- see database/schema.py's own column comment), `branch_id`
    because re-pricing a draft against a DIFFERENT branch's promotions is a
    bigger change than "edit this quote" and is out of v33's scope -- both
    are re-read from the stored row, never from the request body.

    Lines are replaced WHOLESALE and every price is re-resolved server-side
    -- the identical sequence create_quotation uses. Safe only because a
    draft has never synced (see the section banner's DRAFTS DO NOT SYNC):
    there is no peer device holding a stale copy of these lines to
    reconcile, so a plain delete-then-reinsert has no wire consequence.
    """
    data = request.json or {}
    cid = _cid()
    items = data.get('items') or []

    if _wants_discount(items) and not session_has_capability(CAP_DISCOUNT):
        return jsonify({'status': 'error', 'message': DISCOUNT_DENIED_MESSAGE}), 403

    conn = get_retail_conn()
    # See create_quotation's identical call/comment above -- this route also
    # reads `retail_settings` via `_settings()` below.
    _ensure_credit_schema(conn)
    try:
        conn.execute("BEGIN IMMEDIATE")
        row = conn.execute(
            "SELECT branch_id, status FROM sales_quotations WHERE id=? AND company_id=?", (qid, cid)
        ).fetchone()
        if not row:
            conn.rollback()
            return jsonify({'status': 'error', 'message': 'Quotation not found'}), 404
        if row['status'] != 'draft':
            conn.rollback()
            return jsonify({'status': 'error',
                             'message': f"Cannot edit a quotation that is {row['status']}."}), 409
        bid = row['branch_id']

        _s = _settings(conn, cid)
        mode = _s.get('tax_calculation_mode', tax_engine.DEFAULT_MODE)
        currency = _s.get('base_currency')

        resolved_lines, subtotal, discount, tax, total, line_err = _resolve_quotation_lines_for_write(
            conn, cid, bid, items, mode, currency)
        if line_err:
            conn.rollback()
            return line_err

        now_utc = now_utc_iso()
        cur = conn.cursor()
        cur.execute("""
            UPDATE sales_quotations
               SET customer_id=?, valid_until=?, notes=?, currency=?, tax_mode=?,
                   subtotal=?, discount_amount=?, tax_amount=?, total=?,
                   row_version=row_version+1, updated_at_utc=?
             WHERE id=? AND company_id=? AND status='draft'
        """, (data.get('customer_id'), data.get('valid_until'), data.get('notes', ''), currency, mode,
              subtotal, discount, tax, total, now_utc, qid, cid))
        if cur.rowcount != 1:
            conn.rollback()
            return jsonify({'status': 'error', 'message': 'This quotation is no longer a draft.'}), 409

        cur.execute("DELETE FROM sales_quotation_lines WHERE quotation_id=?", (qid,))
        for line in resolved_lines:
            cur.execute("""
                INSERT INTO sales_quotation_lines
                    (id, quotation_id, product_id, product_name_snapshot, quantity,
                     unit_price, discount_pct, tax_rate, line_total, promotion_name_snapshot, line_no)
                VALUES (?,?,?,?,?,?,?,?,?,?,?)
            """, (_new_uid(), qid, line['product_id'], line['product_name_snapshot'], line['quantity'],
                  line['unit_price'], line['discount_pct'], line['tax_rate'], line['line_total'],
                  line['promotion_name_snapshot'], line['line_no']))
        _audit(conn, 'QUOTATION_UPDATED', 'quotation', qid)
        conn.commit()
    except sqlite3.DatabaseError as exc:
        conn.rollback()
        current_app.logger.exception("update_quotation(%s) failed: %s", qid, exc)
        return jsonify({'status': 'error', 'message': 'Could not update this quotation.'}), 400
    finally:
        conn.close()
    return jsonify({'status': 'success'})


@retail_bp.route('/quotations/<string:qid>/send', methods=['POST'])
@mt_login_required
@mt_require_subsystem('retail')
@require_license_capability("retail.quotation.manage", restricted_mode_allowlist=RETAIL_RESTRICTED_ALLOWLIST)
@mt_require_capability(CAP_SELL)
def send_quotation(qid):
    """draft -> sent. THE ONLY transition that ever embeds lines in a sync
    event -- see the section banner's DRAFTS DO NOT SYNC. `sent` is
    IMMUTABLE from this point on (database/schema.py's STATUS VALUES), so
    the frozen line set embedded in THIS event is the only line data any
    other device will ever see for this quotation.
    """
    cid = _cid()
    conn = get_retail_conn()
    try:
        conn.execute("BEGIN IMMEDIATE")
        cur = conn.cursor()
        q = cur.execute(
            "SELECT * FROM sales_quotations WHERE id=? AND company_id=?", (qid, cid)
        ).fetchone()
        if not q:
            conn.rollback()
            return jsonify({'status': 'error', 'message': 'Quotation not found'}), 404
        if q['status'] != 'draft':
            conn.rollback()
            return jsonify({'status': 'error',
                             'message': f"Cannot send a quotation that is {q['status']}."}), 409

        now = now_utc_iso()
        cur.execute("""
            UPDATE sales_quotations
               SET status='sent', sent_at=?, row_version=row_version+1, updated_at_utc=?
             WHERE id=? AND company_id=? AND status='draft'
        """, (now, now, qid, cid))
        if cur.rowcount != 1:
            conn.rollback()
            return jsonify({'status': 'error', 'message': 'This quotation is no longer a draft.'}), 409

        lines = cur.execute(
            "SELECT * FROM sales_quotation_lines WHERE quotation_id=? ORDER BY line_no", (qid,)
        ).fetchall()
        updated = cur.execute("SELECT * FROM sales_quotations WHERE id=?", (qid,)).fetchone()
        payload = _quotation_sync_header_payload(conn, updated)
        payload['lines'] = [
            {'id': ln['id'], 'product_id': ln['product_id'],
             'product_name_snapshot': ln['product_name_snapshot'], 'quantity': ln['quantity'],
             'unit_price': ln['unit_price'], 'discount_pct': ln['discount_pct'],
             'tax_rate': ln['tax_rate'], 'line_total': ln['line_total'],
             'promotion_name_snapshot': ln['promotion_name_snapshot'], 'line_no': ln['line_no']}
            for ln in lines
        ]
        _queue_sync_event(cur, 'quotation', qid, 'create', payload)
        _audit(conn, 'QUOTATION_SENT', 'quotation', qid, q['doc_number'])
        conn.commit()
    except sqlite3.DatabaseError as exc:
        conn.rollback()
        current_app.logger.exception("send_quotation(%s) failed: %s", qid, exc)
        return jsonify({'status': 'error', 'message': 'Could not send this quotation.'}), 400
    finally:
        conn.close()
    _sync_nudge()
    return jsonify({'status': 'success'})


